prompt --application/shared_components/security/authorizations/知识中心导航可访问
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(48405321792827728)
,p_name=>unistr('\77E5\8BC6\4E2D\5FC3\5BFC\822A\53EF\8BBF\95EE')
,p_static_id=>unistr('\77E5\8BC6\4E2D\5FC3\5BFC\822A\53EF\8BBF\95EE')
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '    l_feature_rows pls_integer;',
    '    l_feature_on   pls_integer;',
    'begin',
    '    select count(*),',
    '           count(case when type_2 = ''KNOWLEDGE_CENTER'' and status = ''ACTIVE'' then 1 end)',
    '      into l_feature_rows, l_feature_on',
    '      from kbot_apex_platform_config',
    '     where type_1 = ''PLATFORM_FEATURE'';',
    '    if l_feature_rows > 0 and l_feature_on = 0 then',
    '        return false;',
    '    end if;',
    '    if kbot_apex_auth.is_platform_admin(:APP_USER) then',
    '        return true;',
    '    end if;',
    '    for r in (',
    '        select 1',
    '          from kbot_app_member_role mr',
    '          join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
    '          join kbot_app_role ar on ar.app_id = mr.app_id and ar.role_code = mr.role_code and ar.status = ''ACTIVE''',
    '          join kbot_app_role_permission rp on rp.app_id = ar.app_id and rp.role_code = ar.role_code',
    '         where mr.app_id = ''knowledge_retrieval''',
    '           and mr.user_id = :APP_USER',
    '           and mr.status = ''ACTIVE''',
    unistr('           /* \53EA\6709\77E5\8BC6\4E2D\5FC3\9996\9875\81F3\5C11\5B58\5728\4E00\4E2A\53EF\64CD\4F5C\6A21\5757\65F6\624D\663E\793A\5BFC\822A\3002'),
    unistr('              \4EC5\6709 use/upload/review \7684\89D2\8272\4ECD\53EF\4ECE\5DE5\4F5C\53F0\8FDB\5165\804A\5929\3001\4E0A\4F20\6216\5BA1\6279\FF0C'),
    unistr('              \4E0D\518D\8FDB\5165\4E00\4E2A\6CA1\6709\4EFB\4F55\64CD\4F5C\5361\7247\7684\7A7A\9996\9875\3002 */'),
    '           and rp.permission_code in (',
    '               ''knowledge_retrieval:knowledge_manage'',',
    '               ''knowledge_retrieval:data_manage'',',
    '               ''knowledge_retrieval:agent_manage'',',
    '               ''knowledge_retrieval:member_manage'',',
    '               ''knowledge_retrieval:role_manage'',',
    '               ''knowledge_retrieval:api_key_manage''',
    '           )',
    '           and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
    '               select 1 from kbot_app_member_role_scope s',
    '                where s.app_id = mr.app_id and s.user_id = mr.user_id',
    '                  and s.role_code = mr.role_code and s.domain_id = :P0_DOMAIN_ID',
    '           ))',
    '           and rownum = 1',
    '    ) loop',
    '        return true;',
    '    end loop;',
    '    return false;',
    'end;')))).to_clob
,p_error_message=>unistr('\6743\9650\4E0D\8DB3\3002')
,p_caching=>'BY_USER_BY_PAGE_VIEW'
);
end;
