prompt --application/shared_components/security/authorizations/聊天工作区可访问
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(48407262421827728)
,p_name=>unistr('\804A\5929\5DE5\4F5C\533A\53EF\8BBF\95EE')
,p_static_id=>unistr('\804A\5929\5DE5\4F5C\533A\53EF\8BBF\95EE')
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '    l_feature_rows       pls_integer := 0;',
    '    l_knowledge_feature  pls_integer := 0;',
    '    l_aiops_feature      pls_integer := 0;',
    '    l_km_feature         pls_integer := 0;',
    '    l_knowledge_mapped   pls_integer := 0;',
    '    l_aiops_mapped       pls_integer := 0;',
    '    l_km_mapped          pls_integer := 0;',
    'begin',
    '    select count(*),',
    '           count(case when type_2 = ''KNOWLEDGE_CENTER'' and status = ''ACTIVE'' then 1 end),',
    '           count(case when type_2 = ''AIOPS'' and status = ''ACTIVE'' then 1 end),',
    '           count(case when type_2 = ''KM_ASSET'' and status = ''ACTIVE'' then 1 end)',
    '      into l_feature_rows, l_knowledge_feature, l_aiops_feature, l_km_feature',
    '      from kbot_apex_platform_config',
    '     where type_1 = ''PLATFORM_FEATURE'';',
    '',
    '    if l_feature_rows = 0 then',
    '        l_knowledge_feature := 1;',
    '        l_aiops_feature := 1;',
    '        l_km_feature := 1;',
    '    end if;',
    '',
    '    if :P0_DOMAIN_ID is not null then',
    '        select count(case when app_id = ''knowledge_retrieval'' then 1 end),',
    '               count(case when app_id = ''aiops'' then 1 end),',
    '               count(case when app_id = ''km_asset'' then 1 end)',
    '          into l_knowledge_mapped, l_aiops_mapped, l_km_mapped',
    '          from kbot_app_domain',
    '         where domain_id = :P0_DOMAIN_ID',
    '           and status = ''ACTIVE''',
    '           and app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'');',
    '    end if;',
    '',
    '    return (',
    '        l_knowledge_feature = 1',
    '        and l_knowledge_mapped > 0',
    '        and (kbot_apex_auth.is_platform_admin(:APP_USER)',
    '             or kbot_apex_auth.has_permission(''knowledge_retrieval:use''))',
    '    ) or (',
    '        l_aiops_feature = 1',
    '        and l_aiops_mapped > 0',
    '        and (kbot_apex_auth.is_platform_admin(:APP_USER)',
    '             or kbot_apex_auth.has_permission(''aiops:use''))',
    '    ) or (',
    '        l_km_feature = 1',
    '        and l_km_mapped > 0',
    '        and (kbot_apex_auth.is_platform_admin(:APP_USER)',
    '             or kbot_apex_auth.has_permission(''km_asset:use''))',
    '    );',
    'end;')))).to_clob
,p_error_message=>unistr('\5F53\524D\4E1A\52A1\57DF\6CA1\6709\5DF2\542F\7528\4E14\53EF\8BBF\95EE\7684\804A\5929\5E94\7528\3002')
,p_caching=>'BY_USER_BY_PAGE_VIEW'
);
end;
/
