prompt --application/shared_components/security/authorizations/通知中心可访问
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(48402910091827727)
,p_name=>unistr('\901A\77E5\4E2D\5FC3\53EF\8BBF\95EE')
,p_static_id=>unistr('\901A\77E5\4E2D\5FC3\53EF\8BBF\95EE')
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '    l_access_count pls_integer := 0;',
    'begin',
    '    if :P0_DOMAIN_ID is null then',
    '        return false;',
    '    end if;',
    '',
    '    select count(*)',
    '      into l_access_count',
    '      from kbot_app_domain ad',
    '      join kbot_platform_app a',
    '        on a.app_id = ad.app_id',
    '       and a.status = ''ACTIVE''',
    '     where ad.domain_id = :P0_DOMAIN_ID',
    '       and ad.status = ''ACTIVE''',
    '       and ad.app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
    '       and (',
    '           not exists (',
    '               select 1',
    '                 from kbot_apex_platform_config feature_config',
    '                where feature_config.type_1 = ''PLATFORM_FEATURE''',
    '           )',
    '           or exists (',
    '               select 1',
    '                 from kbot_apex_platform_config enabled_feature',
    '                where enabled_feature.type_1 = ''PLATFORM_FEATURE''',
    '                  and enabled_feature.status = ''ACTIVE''',
    '                  and enabled_feature.type_2 = case ad.app_id',
    '                      when ''knowledge_retrieval'' then ''KNOWLEDGE_CENTER''',
    '                      when ''aiops'' then ''AIOPS''',
    '                      when ''km_asset'' then ''KM_ASSET''',
    '                  end',
    '           )',
    '       )',
    '       and (',
    '           kbot_apex_auth.is_platform_admin(:APP_USER)',
    '           or exists (',
    '               select 1',
    '                 from kbot_app_member_role mr',
    '                 join kbot_app_member m',
    '                   on m.app_id = mr.app_id',
    '                  and m.user_id = mr.user_id',
    '                  and m.status = ''ACTIVE''',
    '                 join kbot_platform_user u',
    '                   on u.user_id = mr.user_id',
    '                  and u.status = ''ACTIVE''',
    '                 join kbot_app_role r',
    '                   on r.app_id = mr.app_id',
    '                  and r.role_code = mr.role_code',
    '                  and r.status = ''ACTIVE''',
    '                 join kbot_app_role_permission rp',
    '                   on rp.app_id = r.app_id',
    '                  and rp.role_code = r.role_code',
    '                where mr.app_id = ad.app_id',
    '                  and mr.user_id = :APP_USER',
    '                  and mr.status = ''ACTIVE''',
    '                  and rp.permission_code like ad.app_id || '':%''',
    '                  and (',
    '                      mr.scope_mode = ''ALL_APP_DOMAINS''',
    '                      or exists (',
    '                          select 1',
    '                            from kbot_app_member_role_scope scope_row',
    '                           where scope_row.app_id = mr.app_id',
    '                             and scope_row.user_id = mr.user_id',
    '                             and scope_row.role_code = mr.role_code',
    '                             and scope_row.domain_id = ad.domain_id',
    '                      )',
    '                  )',
    '           )',
    '       );',
    '',
    '    return l_access_count > 0;',
    'end;')))).to_clob
,p_error_message=>unistr('\5F53\524D\4E1A\52A1\57DF\6CA1\6709\5DF2\542F\7528\4E14\53EF\8BBF\95EE\7684\901A\77E5\5E94\7528\3002')
,p_caching=>'BY_USER_BY_PAGE_VIEW'
);
end;
