prompt --application/shared_components/logic/application_processes/p0_get_app_domain_options
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48402598860827647)
,p_process_sequence=>9
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P0_GET_APP_DOMAIN_OPTIONS'
,p_static_id=>'p0-get-app-domain-options'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_app_id varchar2(64) := lower(trim(apex_application.g_x01));',
'begin',
'    if not kbot_apex_auth.is_platform_admin(:APP_USER)',
'       and l_app_id <> lower(trim(v(''P0_AUTH_APP_ID'')))',
'       and not (',
'           v(''APP_PAGE_ID'') = ''21''',
'           and l_app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'       ) then',
unistr('        raise_application_error(-20001, ''\4E0D\80FD\8BFB\53D6\5176\4ED6\5E94\7528\7684\4E1A\52A1\57DF\6620\5C04\3002'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(''app_id'', l_app_id);',
'    apex_json.open_array(''domain_ids'');',
'    if l_app_id is not null and l_app_id <> ''platform'' then',
'        for d in (',
'            select ad.domain_id',
'              from kbot_app_domain ad',
'              join kbot_platform_domain pd',
'                on pd.domain_id = ad.domain_id',
'               and pd.status = ''ACTIVE''',
'              join kbot_platform_app pa',
'                on pa.app_id = ad.app_id',
'               and pa.status = ''ACTIVE''',
'             where ad.app_id = l_app_id',
'               and ad.status = ''ACTIVE''',
'             order by ad.domain_id desc',
'        ) loop',
'            apex_json.write(d.domain_id);',
'        end loop;',
'    end if;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/p0_get_notification_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48402810428827727)
,p_process_sequence=>11
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P0_GET_NOTIFICATION_CONTEXT'
,p_static_id=>'p0-get-notification-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id number;',
'    l_app_id varchar2(64);',
'    l_app_name varchar2(256);',
'    l_domain_name varchar2(256);',
'    l_token varchar2(4000);',
'    l_expires_at varchar2(128);',
'    l_base_url varchar2(4000);',
'    l_platform_token varchar2(4000);',
'    l_platform_expires_at varchar2(128);',
'    l_platform_seq number;',
'    l_response clob;',
'begin',
'    if regexp_like(apex_application.g_x01, ''^\d+$'') then',
'        l_domain_id := to_number(apex_application.g_x01);',
'    elsif regexp_like(v(''P0_DOMAIN_ID''), ''^\d+$'') then',
'        l_domain_id := to_number(v(''P0_DOMAIN_ID''));',
'    end if;',
'    if l_domain_id is null then',
unistr('        raise_application_error(-20001, ''\901A\77E5\4E2D\5FC3\9700\8981\5148\9009\62E9\6709\6548\7684\4E1A\52A1\57DF\3002'');'),
'    end if;',
'',
'    begin',
'        select c003, c007, c010',
'          into l_app_id, l_token, l_expires_at',
'          from (',
'                select t.c003, t.c007, t.c010',
'                  from apex_collections t',
'                 where t.collection_name = ''KBOT_ENTRY_TOKENS''',
'                   and t.c002 = ''BUSINESS''',
'                   and t.c003 = ''knowledge_retrieval''',
'                   and t.c004 = to_char(l_domain_id)',
'                   and t.c010 is not null',
'                   and substr(t.c010, 1, 19) >',
'                       to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'')',
'                 order by case',
'                              when t.c003 = lower(v(''P0_AUTH_APP_ID'')) then 0',
'                              when t.c003 = ''knowledge_retrieval'' then 1',
'                              when t.c003 = ''aiops'' then 2',
'                              when t.c003 = ''km_asset'' then 3',
'                              else 9',
'                          end,',
'                          t.seq_id desc',
'               )',
'         where rownum = 1;',
'    exception',
'        when no_data_found then',
'            select app_id, app_name, domain_name',
'              into l_app_id, l_app_name, l_domain_name',
'              from (',
'                    select c001 app_id, c002 app_name, c004 domain_name',
'                      from apex_collections',
'                     where collection_name = ''KBOT_SSO_ENTRIES''',
'                       and c001 = ''knowledge_retrieval''',
'                       and c003 = to_char(l_domain_id)',
'                     order by case c001',
'                                  when ''knowledge_retrieval'' then 1',
'                                  when ''aiops'' then 2',
'                                  when ''km_asset'' then 3',
'                                  else 9',
'                              end',
'                   )',
'             where rownum = 1;',
'',
'            select max(case when protocol is not null and host is not null then',
'                       protocol || ''://'' || host ||',
'                       case when port is not null then '':'' || to_char(port) end',
'                   end)',
'              into l_base_url',
'              from kbot_apex_platform_config',
'             where type_1 = ''KBOT_SERVICE''',
'               and type_2 = ''SERVICE''',
'               and status = ''ACTIVE'';',
'            if l_base_url is null then',
'                l_base_url := regexp_replace(rtrim(apex_util.host_url(''HOST''), ''/''), '':(8080|8181)$'', '''');',
'            end if;',
'',
'            select seq_id, c007, c010',
'              into l_platform_seq, l_platform_token, l_platform_expires_at',
'              from apex_collections',
'             where collection_name = ''KBOT_ENTRY_TOKENS''',
'               and c001 = ''PLATFORM''',
'               and rownum = 1;',
'            if l_platform_expires_at is null',
'               or substr(l_platform_expires_at, 1, 19) <=',
'                  to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'') then',
'                apex_web_service.g_request_headers.delete;',
'                apex_web_service.g_request_headers(1).name := ''Authorization'';',
'                apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'                apex_web_service.g_request_headers(2).name := ''Accept'';',
'                apex_web_service.g_request_headers(2).value := ''application/json'';',
'                apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'                apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'                l_response := apex_web_service.make_rest_request(',
'                    p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/refresh'',',
'                    p_http_method => ''POST''',
'                );',
'                if apex_web_service.g_status_code <> 200',
'                   or upper(json_value(l_response, ''$.entry_kind'')) <> ''PLATFORM'' then',
unistr('                    raise_application_error(-20002, ''\5E73\53F0\767B\5F55\5DF2\8FC7\671F\FF0C\8BF7\91CD\65B0\767B\5F55\3002'');'),
'                end if;',
'                l_platform_token := json_value(l_response, ''$.access_token'');',
'                l_platform_expires_at := json_value(l_response, ''$.expires_at'');',
'                apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 7, l_platform_token);',
'                apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 10, l_platform_expires_at);',
'            end if;',
'',
'            apex_web_service.g_request_headers.delete;',
'            apex_web_service.g_request_headers(1).name := ''Authorization'';',
'            apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'            apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'            apex_web_service.g_request_headers(2).value := ''application/json'';',
'            apex_web_service.g_request_headers(3).name := ''Accept'';',
'            apex_web_service.g_request_headers(3).value := ''application/json'';',
'            apex_web_service.g_request_headers(4).name := ''X-Request-ID'';',
'            apex_web_service.g_request_headers(4).value := lower(rawtohex(sys_guid()));',
'            l_response := apex_web_service.make_rest_request(',
'                p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/exchange'',',
'                p_http_method => ''POST'',',
'                p_body => json_object(''app_id'' value l_app_id, ''domain_id'' value l_domain_id)',
'            );',
'            if apex_web_service.g_status_code <> 200 then',
unistr('                raise_application_error(-20003, ''\901A\77E5\4E1A\52A1\57DF\4F1A\8BDD\4EA4\6362\5931\8D25\3002'');'),
'            end if;',
'            l_token := json_value(l_response, ''$.access_token'');',
'            l_expires_at := json_value(l_response, ''$.expires_at'');',
'            if l_token is null or l_expires_at is null',
'               or upper(json_value(l_response, ''$.entry_kind'')) <> ''BUSINESS''',
'               or lower(json_value(l_response, ''$.app_id'')) <> l_app_id',
'               or json_value(l_response, ''$.domain_id'' returning number) <> l_domain_id then',
unistr('                raise_application_error(-20004, ''\901A\77E5\4E1A\52A1\57DF\4F1A\8BDD\8FD4\56DE\65E0\6548\3002'');'),
'            end if;',
'            l_domain_name := coalesce(json_value(l_response, ''$.domain_name''), l_domain_name);',
'            apex_collection.delete_members(',
'                p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                p_attr_number => 1,',
'                p_attr_value => l_app_id || '':'' || to_char(l_domain_id)',
'            );',
'            apex_collection.add_member(',
'                p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                p_c001 => l_app_id || '':'' || to_char(l_domain_id),',
'                p_c002 => ''BUSINESS'', p_c003 => l_app_id,',
'                p_c004 => to_char(l_domain_id), p_c005 => l_app_name,',
'                p_c006 => l_domain_name, p_c007 => l_token,',
'                p_c008 => json_value(l_response, ''$.display_name''),',
'                p_c009 => case when lower(json_value(l_response, ''$.must_change_password'')) = ''true'' then ''Y'' else ''N'' end,',
'                p_c010 => l_expires_at',
'            );',
'    end;',
'',
'    apex_util.set_session_state(''P0_NOTIFICATION_TOKEN'', l_token);',
'    apex_util.set_session_state(''P0_NOTIFICATION_EXPIRES_AT'', l_expires_at);',
'    apex_json.open_object;',
'    apex_json.write(''access_token'', l_token);',
'    apex_json.write(''expires_at'', l_expires_at);',
'    apex_json.write(''app_id'', l_app_id);',
'    apex_json.write(''domain_id'', l_domain_id);',
'    apex_json.close_object;',
'exception',
'    when no_data_found then',
unistr('        raise_application_error(-20005, ''\5F53\524D\8D26\53F7\5728\6240\9009\4E1A\52A1\57DF\6CA1\6709\53EF\7528\4E8E\901A\77E5\4E2D\5FC3\7684 \5E94\7528\6388\6743\3002'');'),
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48402910091827727)
);
end;
/
