prompt --application/shared_components/logic/application_processes/p0_set_platform_domain
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48402678286827647)
,p_process_sequence=>9
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P0_SET_PLATFORM_DOMAIN'
,p_static_id=>'p0-set-platform-domain'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_name varchar2(256);',
'    l_is_admin pls_integer;',
'    l_has_platform_entry pls_integer;',
'    l_has_domain_access pls_integer;',
'begin',
'    select count(*)',
'      into l_has_platform_entry',
'      from apex_collections',
'     where collection_name = ''KBOT_ENTRY_TOKENS''',
'       and c001 = ''PLATFORM''',
'       and c007 is not null;',
'',
'    if l_has_platform_entry = 0 or :P0_DOMAIN_ID is null then',
unistr('        raise_application_error(-20001, ''\5F53\524D\4F1A\8BDD\4E0D\80FD\8BBE\7F6E\5168\5C40\4E1A\52A1\57DF\3002'');'),
'    end if;',
'',
'    l_is_admin := case',
'        when kbot_apex_auth.is_platform_admin(:APP_USER) then 1',
'        else 0',
'    end;',
'    begin',
'        select d.name',
'          into l_domain_name',
'          from kbot_platform_domain d',
'         where d.domain_id = :P0_DOMAIN_ID',
'           and d.status = ''ACTIVE''',
'           and exists (',
'                   select 1',
'                     from kbot_app_domain ad',
'                     join kbot_platform_app a',
'                       on a.app_id = ad.app_id',
'                      and a.status = ''ACTIVE''',
'                    where ad.domain_id = d.domain_id',
'                      and ad.status = ''ACTIVE''',
'                      and ad.app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'                      and (',
'                          not exists (',
'                              select 1',
'                                from kbot_apex_platform_config feature_config',
'                               where feature_config.type_1 = ''PLATFORM_FEATURE''',
'                          )',
'                          or exists (',
'                              select 1',
'                                from kbot_apex_platform_config enabled_feature',
'                               where enabled_feature.type_1 = ''PLATFORM_FEATURE''',
'                                 and enabled_feature.status = ''ACTIVE''',
'                                 and enabled_feature.type_2 = case ad.app_id',
'                                     when ''knowledge_retrieval'' then ''KNOWLEDGE_CENTER''',
'                                     when ''aiops'' then ''AIOPS''',
'                                     when ''km_asset'' then ''KM_ASSET''',
'                                 end',
'                          )',
'                      )',
'               );',
'    exception',
'        when no_data_found then',
unistr('            raise_application_error(-20003, ''\4E1A\52A1\57DF\4E0D\5B58\5728\3001\5DF2\505C\7528\6216\4E0D\9002\7528\4E8E\5F53\524D\5DF2\542F\7528\5E94\7528\3002'');'),
'    end;',
'',
'    -- Workbench/platform pages keep a single global Domain selector.',
'    -- Non-admins may switch to any Domain they already hold through',
'    -- an application membership. Do not require platform_admin, and',
'    -- do not bind a missing application in the target Domain.',
'    if l_is_admin = 0 then',
'        select count(*)',
'          into l_has_domain_access',
'          from kbot_platform_domain d',
'         where d.domain_id = :P0_DOMAIN_ID',
'           and d.status = ''ACTIVE''',
'           and exists (',
'                   select 1',
'                     from kbot_app_member_role mr',
'                     join kbot_app_member m',
'                       on m.app_id = mr.app_id',
'                      and m.user_id = mr.user_id',
'                      and m.status = ''ACTIVE''',
'                     join kbot_app_domain ad',
'                       on ad.app_id = mr.app_id',
'                      and ad.domain_id = d.domain_id',
'                      and ad.status = ''ACTIVE''',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                      and r.status = ''ACTIVE''',
'                     join kbot_app_role_permission rp',
'                       on rp.app_id = mr.app_id',
'                      and rp.role_code = mr.role_code',
'                      and rp.permission_code like mr.app_id || '':%''',
'                    where mr.user_id = :APP_USER',
'                      and mr.status = ''ACTIVE''',
'                      and mr.app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'                      and (',
'                          not exists (',
'                              select 1',
'                                from kbot_apex_platform_config feature_config',
'                               where feature_config.type_1 = ''PLATFORM_FEATURE''',
'                          )',
'                          or exists (',
'                              select 1',
'                                from kbot_apex_platform_config enabled_feature',
'                               where enabled_feature.type_1 = ''PLATFORM_FEATURE''',
'                                 and enabled_feature.status = ''ACTIVE''',
'                                 and enabled_feature.type_2 = case mr.app_id',
'                                     when ''knowledge_retrieval'' then ''KNOWLEDGE_CENTER''',
'                                     when ''aiops'' then ''AIOPS''',
'                                     when ''km_asset'' then ''KM_ASSET''',
'                                 end',
'                          )',
'                      )',
'                      and (',
'                          mr.scope_mode = ''ALL_APP_DOMAINS''',
'                          or exists (',
'                              select 1',
'                                from kbot_app_member_role_scope s',
'                               where s.app_id = mr.app_id',
'                                 and s.user_id = mr.user_id',
'                                 and s.role_code = mr.role_code',
'                                 and s.domain_id = d.domain_id',
'                          )',
'                      )',
'               );',
'        if l_has_domain_access = 0 then',
unistr('            raise_application_error(-20002, ''\5F53\524D\8D26\53F7\6CA1\6709\8BE5\4E1A\52A1\57DF\7684\8BBF\95EE\6743\9650\3002'');'),
'        end if;',
'    end if;',
'',
'    apex_util.set_preference(',
'        p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'        p_value      => to_char(:P0_DOMAIN_ID),',
'        p_user       => :APP_USER',
'    );',
'    apex_util.set_session_state(''P0_AUTH_DOMAIN_NAME'', l_domain_name);',
'    if v(''APP_PAGE_ID'') <> ''21''',
'       and apex_collection.collection_exists(''KBOT_AUTH_CONTEXT'') then',
'        for c in (',
'            select seq_id',
'              from apex_collections',
'             where collection_name = ''KBOT_AUTH_CONTEXT''',
'        ) loop',
'            apex_collection.update_member_attribute(''KBOT_AUTH_CONTEXT'', c.seq_id, 3, to_char(:P0_DOMAIN_ID));',
'            apex_collection.update_member_attribute(''KBOT_AUTH_CONTEXT'', c.seq_id, 4, l_domain_name);',
'        end loop;',
'    end if;',
'',
'    for p in (',
'        select column_value page_id',
'          from table(sys.odcinumberlist(',
'              10, 15, 20, 21, 22, 30, 32, 40, 41, 42, 43,',
'              44, 46, 50, 52, 53, 54, 57, 58, 59, 90,',
'              92, 93, 94, 95, 96, 97, 100, 102, 103, 104, 105',
'          ))',
'    ) loop',
'        apex_util.clear_page_cache(p.page_id);',
'    end loop;',
'',
'    apex_json.open_object;',
'    apex_json.write(''reload'', true);',
'    apex_json.close_object;',
'exception',
'    when no_data_found then',
unistr('        raise_application_error(-20003, ''\4E1A\52A1\57DF\4E0D\5B58\5728\3001\5DF2\505C\7528\6216\4E0D\9002\7528\4E8E\5F53\524D\5DF2\542F\7528\5E94\7528\3002'');'),
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/p44_sync_collection
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48403520209827727)
,p_process_sequence=>60
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P44_SYNC_COLLECTION'
,p_static_id=>'p44-sync-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_count number := 0;',
'begin',
'    select count(distinct e.document_version_id)',
'      into l_count',
'      from kbot_kc_collection c',
'      join kbot_kc_evidence e',
'        on e.collection_id = c.collection_id',
'       and e.status = ''ACTIVE''',
'     where c.domain_id = :P0_DOMAIN_ID',
'       and :P44_COLLECTION_ID is not null',
'       and c.collection_id = hextoraw(',
'           replace(:P44_COLLECTION_ID, ''-'', '''')',
'       );',
'',
'    apex_json.open_object;',
'    apex_json.write(''count'', l_count);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
