prompt --application/shared_components/security/authentications/kbot_platform_令牌
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(48398877563827645)
,p_name=>unistr('KBot Platform \4EE4\724C')
,p_static_id=>'kbot-platform-token'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'kbot_platform_authenticate',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'g_kbot_token        VARCHAR2(4000);',
'g_kbot_display_name VARCHAR2(256);',
'g_kbot_entry_kind   VARCHAR2(16);',
'g_kbot_app_id       VARCHAR2(64);',
'g_kbot_domain_id    VARCHAR2(64);',
'g_kbot_domain_name  VARCHAR2(256);',
'g_kbot_force_change VARCHAR2(5);',
'g_kbot_expires_at   VARCHAR2(128);',
'',
'FUNCTION kbot_platform_authenticate (',
'    p_username IN VARCHAR2,',
'    p_password IN VARCHAR2',
') RETURN BOOLEAN IS',
'    l_base_url     varchar2(4000);',
'    l_response     clob;',
'    l_request      clob;',
'    l_token        varchar2(4000);',
'    l_login_user   varchar2(256);',
'    l_user_id      varchar2(256);',
'    l_display_name varchar2(256);',
'    l_domain_id    number;',
'    l_domain_name  varchar2(256);',
'    l_force_change varchar2(5);',
'    l_expires_at   varchar2(128);',
'    l_entry_kind   varchar2(16);',
'    l_app_id       varchar2(64);',
'    l_app_name     varchar2(256);',
'    l_app_url_id   varchar2(64);',
'    l_apps_response clob;',
'    l_domains_response clob;',
'    l_entries_response clob;',
'    l_target_access_count pls_integer;',
'    l_required_app_id constant varchar2(64) := ''knowledge_retrieval'';',
'begin',
'    if p_username is null or p_password is null then',
'        return false;',
'    end if;',
'',
'    l_login_user := upper(trim(p_username));',
'',
'    select max(',
'               case',
'                   when protocol is not null and host is not null then',
'                       protocol || ''://'' || host ||',
'                       case when port is not null then '':'' || to_char(port) end',
'               end',
'           )',
'      into l_base_url',
'      from kbot_apex_platform_config',
'     where type_1 = ''KBOT_SERVICE''',
'       and type_2 = ''SERVICE''',
'       and status = ''ACTIVE'';',
'',
'    if l_base_url is null then',
'        l_base_url := regexp_replace(',
'            rtrim(apex_util.host_url(''HOST''), ''/''),',
'            '':(8080|8181)$'',',
'            ''''',
'        );',
'    end if;',
'',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    apex_web_service.g_request_headers(2).name := ''Accept'';',
'    apex_web_service.g_request_headers(2).value := ''application/json'';',
'    apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'    apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'',
'    l_request := json_object(',
'        ''user_id'' value l_login_user,',
'        ''password'' value p_password',
'    );',
'',
'    l_entry_kind := ''PLATFORM'';',
'    l_response := apex_web_service.make_rest_request(',
'        p_url         => rtrim(l_base_url, ''/'') || ''/api/v1/auth/platform/login'',',
'        p_http_method => ''POST'',',
'        p_body        => l_request',
'    );',
'    if apex_web_service.g_status_code = 200 then',
'        l_token := json_value(l_response, ''$.access_token'');',
'        l_user_id := json_value(l_response, ''$.user_id'');',
'        l_display_name := json_value(l_response, ''$.display_name'');',
'        l_app_id := json_value(l_response, ''$.app_id'');',
'        l_domain_id := json_value(l_response, ''$.domain_id'' returning number);',
'        l_domain_name := json_value(l_response, ''$.domain_name'');',
'        l_expires_at := json_value(l_response, ''$.expires_at'');',
'        if l_token is null',
'           or upper(trim(l_user_id)) <> l_login_user',
'           or upper(json_value(l_response, ''$.entry_kind'')) <> ''PLATFORM''',
'           or l_app_id is not null',
'           or l_domain_id is not null',
'           or l_expires_at is null then',
'            return false;',
'        end if;',
'        l_app_id := l_required_app_id;',
'',
unistr('        /* \5E73\53F0\6765\6E90\8D26\53F7\4E5F\5FC5\987B\5728\5EFA\7ACB APEX \4F1A\8BDD\524D\62E5\6709\76EE\6807 App \7684'),
unistr('           \6709\6548 :use \6743\9650\53CA\81F3\5C11\4E00\4E2A\53EF\7528 Domain\FF1B\5E73\53F0\7BA1\7406\5458\4F8B\5916\3002'),
unistr('           \6B64\5904\76F4\63A5\6838\5BF9\7EDF\4E00\6743\9650\8868\FF0C\786E\4FDD\9996\6B21\5F3A\5236\6539\5BC6\8D26\53F7\540C\6837\53D7\63A7\3002 */'),
'        if not kbot_apex_auth.is_platform_admin(l_user_id) then',
'            select count(*)',
'              into l_target_access_count',
'              from dual',
'             where exists (',
'                   select 1',
'                     from kbot_app_member m',
'                     join kbot_app_member_role mr',
'                       on mr.app_id = m.app_id',
'                      and mr.user_id = m.user_id',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                     join kbot_app_role_permission rp',
'                       on rp.app_id = r.app_id',
'                      and rp.role_code = r.role_code',
'                     join kbot_platform_app a',
'                       on a.app_id = m.app_id',
'                     join kbot_app_domain ad',
'                       on ad.app_id = m.app_id',
'                     join kbot_platform_domain d',
'                       on d.domain_id = ad.domain_id',
'                     join kbot_platform_user u',
'                       on u.user_id = m.user_id',
'                    where m.app_id = l_required_app_id',
'                      and upper(m.user_id) = upper(l_user_id)',
'                      and m.status = ''ACTIVE''',
'                      and mr.status = ''ACTIVE''',
'                      and r.status = ''ACTIVE''',
'                      and a.status = ''ACTIVE''',
'                      and ad.status = ''ACTIVE''',
'                      and d.status = ''ACTIVE''',
'                      and u.status = ''ACTIVE''',
'                      and rp.permission_code = l_required_app_id || '':use''',
'                      and (',
'                          mr.scope_mode = ''ALL_APP_DOMAINS''',
'                          or exists (',
'                              select 1',
'                                from kbot_app_member_role_scope s',
'                               where s.app_id = mr.app_id',
'                                 and s.user_id = mr.user_id',
'                                 and s.role_code = mr.role_code',
'                                 and s.domain_id = ad.domain_id',
'                          )',
'                      )',
'               );',
'',
'            if l_target_access_count = 0 then',
'                apex_util.remove_preference(',
'                    p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                    p_user       => l_login_user',
'                );',
'                apex_util.set_custom_auth_status(',
unistr('                    ''\5F53\524D\8D26\53F7\6CA1\6709\8FDB\5165\6B64\5E94\7528\7684\6743\9650\3002'''),
'                );',
'                return false;',
'            end if;',
'        end if;',
'    else',
unistr('        /* App \6765\6E90\8D26\53F7\4E0D\80FD\4F7F\7528\5E73\53F0\767B\5F55\63A5\53E3\3002\6CBF\7528\540C\4E00\767B\5F55\9875\FF0C\6309 Python'),
unistr('           \56FA\5B9A\5951\7EA6\53D1\73B0\5176\6240\5C5E App \548C\53EF\7528 Domain\FF0C\5E76\8FDB\5165\9996\4E2A\6709\6548\4E1A\52A1\57DF\FF1B'),
unistr('           \767B\5F55\540E\4ECD\53EF\901A\8FC7\9876\90E8 Domain \9009\62E9\5668\5207\6362\5176\4ED6\5DF2\6388\6743\4E1A\52A1\57DF\3002 */'),
'        apex_web_service.g_request_headers.delete;',
'        apex_web_service.g_request_headers(1).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := ''application/json'';',
'        apex_web_service.g_request_headers(2).name := ''Accept'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'        apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'        l_apps_response := apex_web_service.make_rest_request(',
'            p_url         => rtrim(l_base_url, ''/'') || ''/api/v1/auth/apps'',',
'            p_http_method => ''POST'',',
'            p_body        => l_request',
'        );',
'        if apex_web_service.g_status_code <> 200',
'           or upper(json_value(l_apps_response, ''$.account_origin'')) <> ''APP'' then',
'            return false;',
'        end if;',
'',
'        begin',
'            select app_id, app_name',
'              into l_app_id, l_app_name',
'              from (',
'                    select app_id, app_name',
'                      from json_table(',
'                               l_apps_response,',
'                               ''$.apps[*]'' columns (',
'                                   app_id varchar2(64) path ''$.app_id'',',
'                                   app_name varchar2(256) path ''$.display_name'',',
'                                   app_status varchar2(16) path ''$.status''',
'                               )',
'                           )',
'                     where app_id = l_required_app_id',
'                       and upper(app_status) = ''ACTIVE''',
'                     order by app_id',
'                   )',
'             where rownum = 1;',
'        exception',
'            WHEN no_data_found THEN',
'                apex_util.remove_preference(',
'                    p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                    p_user       => l_login_user',
'                );',
unistr('                apex_util.set_custom_auth_status(''\5F53\524D\8D26\53F7\6CA1\6709\53EF\7528\4E1A\52A1\5E94\7528\3002'');'),
'                RETURN false;',
'        end;',
'',
'        l_app_url_id := case l_app_id',
'            when ''knowledge_retrieval'' then ''knowledge-retrieval''',
'            when ''km_asset'' then ''km-asset''',
'            else l_app_id',
'        end;',
'        apex_web_service.g_request_headers.delete;',
'        apex_web_service.g_request_headers(1).name := ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := ''application/json'';',
'        apex_web_service.g_request_headers(2).name := ''Accept'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'        apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'        l_domains_response := apex_web_service.make_rest_request(',
'            p_url         => rtrim(l_base_url, ''/'') || ''/api/v1/auth/apps/'' || l_app_url_id || ''/domains'',',
'            p_http_method => ''POST'',',
'            p_body        => l_request',
'        );',
'        if apex_web_service.g_status_code <> 200 then',
'            return false;',
'        end if;',
'        begin',
'            select domain_id, domain_name',
'              into l_domain_id, l_domain_name',
'              from (',
'                    select domain_id, domain_name',
'                      from json_table(',
'                               l_domains_response,',
'                               ''$.domains[*]'' columns (',
'                                   domain_id number path ''$.domain_id'',',
'                                   domain_name varchar2(256) path ''$.name'',',
'                                   domain_status varchar2(16) path ''$.status''',
'                               )',
'                           )',
'                     where upper(domain_status) = ''ACTIVE''',
'                     order by case',
'                                  when domain_id = coalesce(',
'                                      case',
'                                          when regexp_like(',
'                                              apex_util.get_preference(',
'                                                  ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                                                  l_login_user',
'                                              ),',
'                                              ''^\d+$''',
'                                          ) then to_number(',
'                                              apex_util.get_preference(',
'                                                  ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                                                  l_login_user',
'                                              )',
'                                          )',
'                                      end,',
'                                      kbot_apex_auth.preferred_domain_id(l_login_user)',
'                                  )',
'                                  then 0',
'                                  else 1',
'                              end,',
'                              domain_id desc',
'                   )',
'             where rownum = 1;',
'        exception',
'            WHEN no_data_found THEN',
'                apex_util.remove_preference(',
'                    p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                    p_user       => l_login_user',
'                );',
unistr('                apex_util.set_custom_auth_status(''\5F53\524D\8D26\53F7\6CA1\6709\53EF\7528\4E1A\52A1\57DF\3002'');'),
'                RETURN false;',
'        end;',
'',
'        l_entry_kind := ''BUSINESS'';',
'        l_response := apex_web_service.make_rest_request(',
'            p_url         => rtrim(l_base_url, ''/'') || ''/api/v1/auth/apps/'' || l_app_url_id || ''/login'',',
'            p_http_method => ''POST'',',
'            p_body        => json_object(',
'                ''user_id'' value l_login_user,',
'                ''password'' value p_password,',
'                ''domain_id'' value l_domain_id',
'            )',
'        );',
'        if apex_web_service.g_status_code <> 200 then',
'            return false;',
'        end if;',
'        l_token := json_value(l_response, ''$.access_token'');',
'        l_user_id := json_value(l_response, ''$.user_id'');',
'        l_display_name := json_value(l_response, ''$.display_name'');',
'        l_domain_id := json_value(l_response, ''$.domain_id'' returning number);',
'        l_domain_name := json_value(l_response, ''$.domain_name'');',
'        l_expires_at := json_value(l_response, ''$.expires_at'');',
'        if l_token is null',
'           or upper(trim(l_user_id)) <> l_login_user',
'           or upper(json_value(l_response, ''$.entry_kind'')) <> ''BUSINESS''',
'           or json_value(l_response, ''$.app_id'') <> l_app_id',
'           or l_domain_id is null',
'           or l_expires_at is null then',
'            return false;',
'        end if;',
'    end if;',
'    l_force_change := case',
'        when lower(json_value(l_response, ''$.must_change_password'')) = ''true'' then ''Y''',
'        else ''N''',
'    end;',
'',
'    apex_collection.create_or_truncate_collection(',
'        p_collection_name => ''KBOT_ENTRY_TOKENS''',
'    );',
'    apex_collection.add_member(',
'        p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'        p_c001 => case when l_entry_kind = ''PLATFORM'' then ''PLATFORM'' else l_app_id || '':'' || to_char(l_domain_id) end,',
'        p_c002 => l_entry_kind,',
'        p_c003 => l_app_id,',
'        p_c004 => to_char(l_domain_id),',
unistr('        p_c005 => case when l_entry_kind = ''PLATFORM'' then ''\5E73\53F0\63A7\5236\53F0'' else l_app_id end,'),
'        p_c006 => l_domain_name,',
'        p_c007 => l_token,',
'        p_c008 => l_display_name,',
'        p_c009 => l_force_change,',
'        p_c010 => l_expires_at',
'    );',
'',
'    apex_collection.create_or_truncate_collection(',
'        p_collection_name => ''KBOT_SSO_ENTRIES''',
'    );',
unistr('    /* \9996\6B21\6539\5BC6\7684\5E73\53F0 Token \53EA\80FD\8BFB\53D6\5F53\524D\7528\6237\548C\4FEE\6539\5BC6\7801\3002'),
unistr('       \8DF3\8FC7\666E\901A SSO \5165\53E3\53D1\73B0\FF0C\8BA9 APEX \4F1A\8BDD\5148\8FDB\5165\5DE5\4F5C\53F0\5F39\51FA\5F3A\5236\6539\5BC6\6846\FF1B'),
unistr('       \6539\5BC6\6210\529F\6CE8\9500\540E\FF0C\4E0B\4E00\6B21\767B\5F55\518D\6309\5E38\89C4\6D41\7A0B\52A0\8F7D\4E1A\52A1\5165\53E3\3002 */'),
'    if l_entry_kind = ''PLATFORM'' and l_force_change <> ''Y'' then',
'        apex_web_service.g_request_headers.delete;',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := ''Bearer '' || l_token;',
'        apex_web_service.g_request_headers(2).name := ''Accept'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'        apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'        l_entries_response := apex_web_service.make_rest_request(',
'            p_url         => rtrim(l_base_url, ''/'') || ''/api/v1/auth/entries'',',
'            p_http_method => ''GET''',
'        );',
'        if apex_web_service.g_status_code <> 200 then',
'            return false;',
'        end if;',
'        for entry_row in (',
'            select app_id, app_name, domain_id, domain_name',
'              from json_table(',
'                       l_entries_response,',
'                       ''$.apps[*]'' columns (',
'                           app_id varchar2(64) path ''$.app_id'',',
'                           app_name varchar2(256) path ''$.display_name'',',
'                           nested path ''$.domains[*]'' columns (',
'                               domain_id number path ''$.domain_id'',',
'                               domain_name varchar2(256) path ''$.name''',
'                           )',
'                       )',
'                   )',
'             where app_id = l_required_app_id',
'               and domain_id is not null',
'        ) loop',
'            apex_collection.add_member(',
'                p_collection_name => ''KBOT_SSO_ENTRIES'',',
'                p_c001 => entry_row.app_id,',
'                p_c002 => entry_row.app_name,',
'                p_c003 => to_char(entry_row.domain_id),',
'                p_c004 => entry_row.domain_name',
'            );',
'        end loop;',
'    elsif l_entry_kind <> ''PLATFORM'' then',
'        for domain_row in (',
'            select domain_id, domain_name',
'              from json_table(',
'                       l_domains_response,',
'                       ''$.domains[*]'' columns (',
'                           domain_id number path ''$.domain_id'',',
'                           domain_name varchar2(256) path ''$.name'',',
'                           domain_status varchar2(16) path ''$.status''',
'                       )',
'                   )',
'             where upper(domain_status) = ''ACTIVE''',
'        ) loop',
'            apex_collection.add_member(',
'                p_collection_name => ''KBOT_SSO_ENTRIES'',',
'                p_c001 => l_app_id,',
'                p_c002 => l_app_name,',
'                p_c003 => to_char(domain_row.domain_id),',
'                p_c004 => domain_row.domain_name',
'            );',
'        end loop;',
'    end if;',
'',
'    g_kbot_token := l_token;',
'    g_kbot_display_name := l_display_name;',
'    g_kbot_entry_kind := l_entry_kind;',
'    g_kbot_app_id := l_app_id;',
'    g_kbot_domain_id := to_char(l_domain_id);',
'    g_kbot_domain_name := l_domain_name;',
'    g_kbot_force_change := l_force_change;',
'    g_kbot_expires_at := l_expires_at;',
'',
'    apex_collection.create_or_truncate_collection(',
'        p_collection_name => ''KBOT_AUTH_CONTEXT''',
'    );',
'    apex_collection.add_member(',
'        p_collection_name => ''KBOT_AUTH_CONTEXT'',',
'        p_c001            => l_token,',
'        p_c002            => l_display_name,',
'        p_c003            => to_char(l_domain_id),',
'        p_c004            => l_domain_name,',
'        p_c005            => l_force_change',
'        ,p_c006            => l_entry_kind',
'        ,p_c007            => l_app_id',
'        ,p_c008            => l_expires_at',
'    );',
'    return true;',
'exception',
'    when others then',
'        return false;',
'end kbot_platform_authenticate;',
'',
'PROCEDURE kbot_platform_after_login IS',
'BEGIN',
'    apex_util.set_session_state(''P0_USER_TOKEN'', g_kbot_token);',
'    apex_util.set_session_state(''P0_DOMAIN_ID'', g_kbot_domain_id);',
