 p_id=>wwv_flow_imp.id(48423313276830286)
,p_name=>'P0_DOMAIN_ID'
,p_item_sequence=>25
,p_item_plug_id=>wwv_flow_imp.id(48421313207830243)
,p_prompt=>unistr('\4E1A\52A1\57DF')
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with f as (',
' select count(*) n,',
'        count(case when type_2=''KNOWLEDGE_CENTER'' and status=''ACTIVE'' then 1 end) kc',
' from kbot_apex_platform_config where type_1=''PLATFORM_FEATURE''',
'), e as (',
' select ad.domain_id,ad.app_id',
' from kbot_app_domain ad',
' join kbot_platform_app a on a.app_id=ad.app_id and a.status=''ACTIVE''',
' cross join f',
' where ad.status=''ACTIVE''',
' and ad.app_id = ''knowledge_retrieval''',
' and (f.n=0 or f.kc>0)',
')',
'select coalesce(max(case when d.domain_id=:P0_DOMAIN_ID then d.domain_id end),',
' max(case when d.domain_id=coalesce(',
'     case',
'      when regexp_like(apex_util.get_preference(''KBOT_DOMAIN_APP_''||v(''APP_ID''),:APP_USER),''^\d+$'')',
'      then to_number(apex_util.get_preference(''KBOT_DOMAIN_APP_''||v(''APP_ID''),:APP_USER))',
'     end,',
'     kbot_apex_auth.preferred_domain_id(:APP_USER)',
'    ) then d.domain_id end),max(d.domain_id))',
'from kbot_platform_domain d',
'where d.status=''ACTIVE'' and (',
' (kbot_apex_auth.is_platform_admin(:APP_USER) and exists(select 1 from e where e.domain_id=d.domain_id))',
' or (v(''P0_AUTH_ENTRY_KIND'')=''PLATFORM'' and exists(',
'  select 1 from kbot_app_member_role mr',
'  join kbot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE''',
'  join e on e.app_id=mr.app_id and e.domain_id=d.domain_id',
'  join kbot_app_role r on r.app_id=mr.app_id and r.role_code=mr.role_code and r.status=''ACTIVE''',
'  join kbot_app_role_permission rp on rp.app_id=mr.app_id and rp.role_code=mr.role_code and rp.permission_code like mr.app_id||'':%''',
'  where mr.user_id=:APP_USER and mr.status=''ACTIVE''',
'  and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(',
'   select 1 from kbot_app_member_role_scope s',
'   where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=d.domain_id',
'  ))',
' ))',
' or (v(''P0_AUTH_ENTRY_KIND'')=''BUSINESS'' and exists(',
'  select 1 from kbot_app_member_role mr',
'  join kbot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE''',
'  join e on e.app_id=mr.app_id and e.domain_id=d.domain_id',
'  where mr.app_id=v(''P0_AUTH_APP_ID'') and mr.user_id=:APP_USER and mr.status=''ACTIVE''',
'  and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(',
'   select 1 from kbot_app_member_role_scope s',
'   where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=d.domain_id',
'  ))',
' ))',
')'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with f as (',
' select count(*) n,',
'        count(case when type_2=''KNOWLEDGE_CENTER'' and status=''ACTIVE'' then 1 end) kc',
' from kbot_apex_platform_config where type_1=''PLATFORM_FEATURE''',
'), e as (',
' select ad.domain_id,ad.app_id',
' from kbot_app_domain ad',
' join kbot_platform_app a on a.app_id=ad.app_id and a.status=''ACTIVE''',
' cross join f',
' where ad.status=''ACTIVE''',
' and ad.app_id = ''knowledge_retrieval''',
' and (f.n=0 or f.kc>0)',
')',
'select d.name display_value,d.domain_id return_value',
'from kbot_platform_domain d',
'where d.status=''ACTIVE'' and (',
' (kbot_apex_auth.is_platform_admin(:APP_USER) and exists(select 1 from e where e.domain_id=d.domain_id))',
' or (v(''P0_AUTH_ENTRY_KIND'')=''PLATFORM'' and exists(',
'  select 1 from kbot_app_member_role mr',
'  join kbot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE''',
'  join e on e.app_id=mr.app_id and e.domain_id=d.domain_id',
'  join kbot_app_role r on r.app_id=mr.app_id and r.role_code=mr.role_code and r.status=''ACTIVE''',
'  join kbot_app_role_permission rp on rp.app_id=mr.app_id and rp.role_code=mr.role_code and rp.permission_code like mr.app_id||'':%''',
'  where mr.user_id=:APP_USER and mr.status=''ACTIVE''',
'  and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(',
'   select 1 from kbot_app_member_role_scope s',
'   where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=d.domain_id',
'  ))',
' ))',
' or (v(''P0_AUTH_ENTRY_KIND'')=''BUSINESS'' and exists(',
'  select 1 from kbot_app_member_role mr',
'  join kbot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE''',
'  join e on e.app_id=mr.app_id and e.domain_id=d.domain_id',
'  where mr.app_id=v(''P0_AUTH_APP_ID'') and mr.user_id=:APP_USER and mr.status=''ACTIVE''',
'  and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(',
'   select 1 from kbot_app_member_role_scope s',
'   where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=d.domain_id',
'  ))',
' ))',
')',
'order by d.domain_id desc'))
,p_cHeight=>1
,p_label_alignment=>'RIGHT-CENTER'
,p_field_alignment=>'LEFT-CENTER'
,p_field_template=>2042262243893469891
,p_item_icon_css_classes=>'fa-sitemap'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(48423048361830244)
,p_name=>'P0_FEATURE_KNOWLEDGE'
,p_item_sequence=>29
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case',
'           when (',
'               not exists (',
'                   select 1',
'                     from kbot_apex_platform_config',
'                    where type_1 = ''PLATFORM_FEATURE''',
'               )',
'               or exists (',
'                   select 1',
'                     from kbot_apex_platform_config',
'                    where type_1 = ''PLATFORM_FEATURE''',
'                      and type_2 = ''KNOWLEDGE_CENTER''',
'                      and status = ''ACTIVE''',
'               )',
'           ) and (',
'               kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or exists (',
'               select 1',
'                 from kbot_app_member_role mr',
'                 join kbot_app_member m',
'                   on m.app_id = mr.app_id',
'                  and m.user_id = mr.user_id',
'                  and m.status = ''ACTIVE''',
'                 join kbot_app_domain ad',
'                   on ad.app_id = mr.app_id',
'                  and ad.domain_id = :P0_DOMAIN_ID',
'                  and ad.status = ''ACTIVE''',
'                 join kbot_platform_user u',
'                   on u.user_id = mr.user_id',
'                  and u.status = ''ACTIVE''',
'                 join kbot_app_role r',
'                   on r.app_id = mr.app_id',
'                  and r.role_code = mr.role_code',
'                  and r.status = ''ACTIVE''',
'                 join kbot_app_role_permission rp',
'                   on rp.app_id = r.app_id',
'                  and rp.role_code = r.role_code',
'                where mr.app_id = ''knowledge_retrieval''',
'                  and mr.user_id = :APP_USER',
'                  and mr.status = ''ACTIVE''',
'                  and rp.permission_code like ''knowledge_retrieval:%''',
'                  and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
'                      select 1',
