,p_name=>unistr('\6CE8\518C\5E94\7528\542F\52A8\6807\7B7E\9875')
,p_static_id=>'p0-register-launch-presence'
,p_event_sequence=>1
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'ready'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(49677937039439144)
,p_event_id=>wwv_flow_imp.id(49677822568439144)
,p_event_result=>'TRUE'
,p_action_sequence=>1
,p_static_id=>'p0-register-launch-presence-js'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '(function () {',
    '    if (window.__kbotLaunchPresenceRegistered) {',
    '        return;',
    '    }',
    '',
    '    const appId = String(window.apex?.env?.APP_ID || "");',
    '    if (!appId) {',
    '        return;',
    '    }',
    '',
    '    window.__kbotLaunchPresenceRegistered = true;',
    '    const presenceKey = `kbot:agent-window:${appId}`;',
    '    const focusKey = `${presenceKey}:focus`;',
    '    const focusAckKey = `${focusKey}:ack`;',
    '    const tabId = window.crypto?.randomUUID?.() ||',
    '        `${Date.now()}-${Math.random().toString(36).slice(2)}`;',
    '',
    '    const publishPresence = function () {',
    '        localStorage.setItem(presenceKey, JSON.stringify({',
    '            tabId,',
    '            updatedAt: Date.now()',
    '        }));',
    '    };',
    '',
    '    const ownsPresence = function () {',
    '        try {',
    '            const current = JSON.parse(localStorage.getItem(presenceKey) || "null");',
    '            return current?.tabId === tabId;',
    '        } catch (error) {',
    '            return false;',
    '        }',
    '    };',
    '',
    '    const clearPresence = function () {',
    '        window.clearInterval(window.__kbotLaunchPresenceTimer);',
    '        try {',
    '            if (ownsPresence()) {',
    '                localStorage.removeItem(presenceKey);',
    '            }',
    '            const acknowledgement = JSON.parse(',
    '                localStorage.getItem(focusAckKey) || "null"',
    '            );',
    '            if (acknowledgement?.tabId === tabId) {',
    '                localStorage.removeItem(focusAckKey);',
    '            }',
    '        } catch (error) {',
    '            localStorage.removeItem(presenceKey);',
    '        }',
    '    };',
    '',
    '    publishPresence();',
    '    window.__kbotLaunchPresenceTimer = window.setInterval(publishPresence, 2000);',
    '    window.addEventListener("focus", publishPresence);',
    '    document.addEventListener("visibilitychange", function () {',
    '        if (!document.hidden) {',
    '            publishPresence();',
    '        }',
    '    });',
    '    window.addEventListener("storage", function (event) {',
    '        if (event.key !== focusKey || !event.newValue) {',
    '            return;',
    '        }',
    '        try {',
    '            const request = JSON.parse(event.newValue);',
    '            if (!request?.requestId) {',
    '                return;',
    '            }',
    '            publishPresence();',
    '            localStorage.setItem(focusAckKey, JSON.stringify({',
    '                requestId: request.requestId,',
    '                tabId,',
    '                acknowledgedAt: Date.now()',
    '            }));',
    '            window.focus();',
    '        } catch (error) {',
    '            return;',
    '        }',
    '    });',
    '    window.addEventListener("pagehide", clearPresence, { once: true });',
    '}());')))).to_clob
);
end;
/
