'declare',
'    l_domain_id number; l_domain_name varchar2(256); l_is_platform_admin boolean := kbot_apex_auth.is_platform_admin(:APP_USER);',
'    l_identity_label varchar2(4000); l_feature_rows pls_integer := 0; l_feature pls_integer := 0; l_mapped pls_integer := 0;',
'    l_authorized boolean := false; l_available boolean := false; l_all_permissions varchar2(32767);',
'begin',
'    begin l_domain_id := to_number(nullif(trim(v(''P0_DOMAIN_ID'')), '''')); exception when value_error then l_domain_id := null; end;',
'    if l_domain_id is not null then select max(name) into l_domain_name from kbot_platform_domain where domain_id=l_domain_id and status=''ACTIVE''; end if;',
'    select listagg(permission_code,''|'') within group(order by permission_code) into l_all_permissions from (',
'      select distinct rp.permission_code from kbot_platform_user_role ur join kbot_platform_user u on u.user_id=ur.user_id and u.status=''ACTIVE'' join kbot_app_role r on r.app_id=''platform'' and r.role_code=ur.role_code and r.status=''ACTIVE'' join kbot_'
||'app_role_permission rp on rp.app_id=r.app_id and rp.role_code=r.role_code where ur.user_id=:APP_USER and ur.status=''ACTIVE''',
'      union',
'      select distinct rp.permission_code from kbot_app_member_role mr join kbot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE'' join kbot_platform_app a on a.app_id=mr.app_id and a.status=''ACTIVE'' join kbot_app_domai'
||'n ad on ad.app_id=mr.app_id and ad.domain_id=l_domain_id and ad.status=''ACTIVE'' join kbot_platform_user u on u.user_id=mr.user_id and u.status=''ACTIVE'' join kbot_app_role r on r.app_id=mr.app_id and r.role_code=mr.role_code and r.status=''ACTIVE'' join'
||' kbot_app_role_permission rp on rp.app_id=r.app_id and rp.role_code=r.role_code where mr.app_id=''knowledge_retrieval'' and mr.user_id=:APP_USER and mr.status=''ACTIVE'' and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(select 1 from kbot_app_member_role_sc'
||'ope s where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=l_domain_id))',
'    );',
unistr('    if l_is_platform_admin then l_identity_label := ''\5E73\53F0\7BA1\7406\5458''; else select listagg(display_name,''\3001'') within group(order by upper(display_name),display_name) into l_identity_label from (select distinct r.display_name from kbot_app_member_role mr join kb')
||'ot_app_member m on m.app_id=mr.app_id and m.user_id=mr.user_id and m.status=''ACTIVE'' join kbot_platform_app a on a.app_id=mr.app_id and a.status=''ACTIVE'' join kbot_app_domain ad on ad.app_id=mr.app_id and ad.domain_id=l_domain_id and ad.status=''ACTIV'
||'E'' join kbot_app_role r on r.app_id=mr.app_id and r.role_code=mr.role_code and r.status=''ACTIVE'' where mr.app_id=''knowledge_retrieval'' and mr.user_id=:APP_USER and mr.status=''ACTIVE'' and (mr.scope_mode=''ALL_APP_DOMAINS'' or exists(select 1 from kbot_a'
||unistr('pp_member_role_scope s where s.app_id=mr.app_id and s.user_id=mr.user_id and s.role_code=mr.role_code and s.domain_id=l_domain_id))); l_identity_label:=nvl(l_identity_label,''\65E0''); end if;'),
'    select count(*),count(case when type_2=''KNOWLEDGE_CENTER'' and status=''ACTIVE'' then 1 end) into l_feature_rows,l_feature from kbot_apex_platform_config where type_1=''PLATFORM_FEATURE''; if l_feature_rows=0 then l_feature:=1; end if;',
'    if l_domain_id is not null then select count(*) into l_mapped from kbot_app_domain where domain_id=l_domain_id and app_id=''knowledge_retrieval'' and status=''ACTIVE''; end if;',
unistr('    l_authorized:=apex_authorization.is_authorized(''\77E5\8BC6\4E2D\5FC3\5BFC\822A\53EF\8BBF\95EE''); l_available:=l_feature=1 and l_mapped>0 and (l_is_platform_admin or regexp_like(nvl(l_all_permissions,'' ''),''(^|\005C|)knowledge_retrieval:[^|]+($|\005C|)''));'),
unistr('    apex_json.open_object; apex_json.write(''domain_id'',l_domain_id); apex_json.write(''domain_name'',nvl(l_domain_name,''\672A\9009\62E9\4E1A\52A1\57DF'')); apex_json.write(''is_platform_admin'',l_is_platform_admin); apex_json.write(''identity_label'',l_identity_label); apex_json.w')
||'rite(''generated_at'',to_char(systimestamp,''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'    apex_json.open_object(''capabilities'');',
'                    apex_json.write(''chat'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:use'', l_all_permissions));',
