'                    apex_json.write(''knowledge_review'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:review'', l_all_permissions));',
'                    apex_json.write(''knowledge_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:knowledge_manage'', l_all_permissions));',
'                    apex_json.write(''knowledge_data_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:data_model_manage'', l_all_permissions));',
'                    apex_json.write(''knowledge_operations_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:knowledge_manage'', l_all_permissions));',
'                    apex_json.write(''knowledge_agent_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''knowledge_retrieval:agent_manage'', l_all_permissions));',
