'    apex_json.close_object; apex_json.open_array(''apps''); apex_json.open_object; apex_json.write(''app_id'',''knowledge_retrieval''); apex_json.write(''feature_enabled'',l_feature=1); apex_json.write(''domain_mapped'',l_mapped>0); apex_json.write(''authorized'
||''',l_authorized); apex_json.write(''available'',l_available); apex_json.write(''attention_count'',0); apex_json.close_object; apex_json.close_array; apex_json.open_object(''metrics''); apex_json.close_object; apex_json.close_object;',
'end;',
'                '))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48423883909830286
