,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P15_GET_RESOURCE_URL'
,p_static_id=>'p15-get-resource-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_resource_type varchar2(80) := lower(apex_application.g_x01);',
'    v_resource_id   varchar2(256) := apex_application.g_x02;',
'    v_url           varchar2(32767);',
'',
'begin',
'    case v_resource_type',
'        when ''agent_run'' then',
'            v_url := apex_page.get_url(p_page => 22, p_clear_cache => ''22'', p_items => ''P22_RUN_ID'', p_values => v_resource_id);',
'        when ''knowledge_collection'' then',
'            v_url := apex_page.get_url(p_page => 41, p_clear_cache => ''41'', p_items => ''P41_COLLECTION_ID'', p_values => v_resource_id);',
'        when ''knowledge_ingestion_repair'' then',
'            v_url := apex_page.get_url(p_page => 46, p_clear_cache => ''46'', p_items => ''P46_COLLECTION_ID'', p_values => v_resource_id);',
'        when ''schema_snapshot'' then',
'            v_url := apex_page.get_url(p_page => 31, p_clear_cache => ''31'', p_items => ''P31_SCHEMA_SNAPSHOT_ID'', p_values => v_resource_id);',
'        when ''semantic_model'' then',
'            v_url := apex_page.get_url(p_page => 31, p_clear_cache => ''31'', p_items => ''P31_SEMANTIC_MODEL_ID'', p_values => v_resource_id);',
'        when ''semantic_model_generation'' then',
'            v_url := apex_page.get_url(p_page => 31, p_clear_cache => ''31'', p_items => ''P31_MODEL_GENERATION_ID'', p_values => v_resource_id);',
'        when ''data_query_run'' then',
'            v_url := apex_page.get_url(p_page => 22, p_clear_cache => ''22'', p_items => ''P22_RUN_ID,P22_RUN_TYPE'', p_values => v_resource_id || '',DATA_QUERY'');',
'        else',
unistr('            raise_application_error(-20001, ''\5F53\524D\8D44\6E90\7C7B\578B\6CA1\6709\5BF9\5E94\9875\9762\3002'');'),
'    end case;',
'',
'    apex_json.open_object;',
'    apex_json.write(''url'', v_url);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48402910091827727)
,p_internal_uid=>48424569847830287
);
