'                l_auth_response := apex_web_service.make_rest_request(',
'                    p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/exchange'',',
'                    p_http_method => ''POST'',',
'                    p_body => json_object(''app_id'' value app_rec.app_id, ''domain_id'' value l_domain_id)',
