 p_id=>wwv_flow_imp.id(48429042361830386)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_GET_CHAT_URL'
,p_static_id=>'p30-get-chat-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_agent_id varchar2(36) := trim(apex_application.g_x01);',
'begin',
'    if not regexp_like(',
'        l_agent_id,',
'        ''^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$''',
'    ) then',
unistr('        raise_application_error(-20001, ''\667A\80FD\4F53 ID \683C\5F0F\65E0\6548\3002'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(',
'        ''url'',',
'        apex_page.get_url(',
'            p_page        => 21,',
'            p_clear_cache => ''21'',',
'            p_items       => ''P21_AGENT_ID,P21_AGENT_SCOPE'',',
'            p_values      => l_agent_id || '',knowledge''',
'        )',
'    );',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48405033366827728)
,p_internal_uid=>48429042361830386
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48428807631830386)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_LOAD_AGENTS'
,p_static_id=>'p30-load-agents'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_json.open_object;',
'apex_json.open_array(''items'');',
'',
'for r in (',
'    select lower(',
'               substr(rawtohex(a.agent_id), 1, 8) || ''-'' ||',
'               substr(rawtohex(a.agent_id), 9, 4) || ''-'' ||',
'               substr(rawtohex(a.agent_id), 13, 4) || ''-'' ||',
'               substr(rawtohex(a.agent_id), 17, 4) || ''-'' ||',
'               substr(rawtohex(a.agent_id), 21, 12)',
'           ) as agent_id,',
'           a.display_name,',
'           a.description,',
'           a.status,',
'           JSON_ARRAY(',
'               ''conversation'',',
'               ''document'',',
'               CASE',
'                   WHEN JSON_EXISTS(v.data_model_ids_json, ''$[0]'')',
'                   THEN ''data_query''',
'               END,',
'               CASE',
'                   WHEN JSON_VALUE(',
'                       v.models_json,',
'                       ''$.x_search_llm''',
'                       RETURNING VARCHAR2(36)',
'                       NULL ON ERROR',
'                   ) IS NOT NULL',
'                   THEN ''x_search''',
'               END',
'               ABSENT ON NULL',
'               RETURNING CLOB',
'           ) AS enabled_capabilities_json,',
'           json_serialize(v.models_json returning clob) as models_json,',
'           v.instruction,',
'           json_serialize(v.config_json returning clob) as config_json,',
'           case',
'               when v.knowledge_core_id is null then null',
'               else lower(',
'                   substr(rawtohex(v.knowledge_core_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(v.knowledge_core_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(v.knowledge_core_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(v.knowledge_core_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(v.knowledge_core_id), 21, 12)',
'               )',
'           end as knowledge_core_id,',
'           case',
'               when kc.collection_id is not null and kc.status = ''ACTIVE'' then 1',
'               else 0',
'           end as has_active_knowledge_core,',
'           to_char(',
'               a.created_at,',
'               ''YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM''',
'           ) as created_at,',
'           case',
'               when exists (',
'                   select 1',
'                     from kbot_kc_collection_binding b',
'                     join kbot_kc_collection c',
'                       on c.collection_id = b.collection_id',
'                    where b.consumer_type = ''AGENT''',
'                      and b.consumer_id = a.agent_id',
'                      and b.status = ''ACTIVE''',
'                      and c.status = ''ACTIVE''',
'               ) then 1',
'               else 0',
'           end as has_active_collection_binding,',
'           a.row_version',
'     from kbot_kr_agent a',
'     join kbot_kr_agent_version v',
'        on v.agent_version_id = a.current_version_id',
'     left join kbot_kc_collection kc',
'        on kc.collection_id = v.knowledge_core_id',
'       and kc.domain_id = a.domain_id',
'     where a.domain_id = :P0_DOMAIN_ID',
'     order by upper(a.display_name), a.agent_id',
') loop',
'    apex_json.open_object;',
'    apex_json.write(''agent_kind'', ''knowledge'');',
'    apex_json.write(''agent_id'', r.agent_id);',
'    apex_json.write(''display_name'', r.display_name);',
'    apex_json.write(''description'', r.description);',
'    apex_json.write(''status'', r.status);',
'    apex_json.write(''enabled_capabilities_json'', r.enabled_capabilities_json);',
'    apex_json.write(''models_json'', r.models_json);',
'    apex_json.write(''instruction'', r.instruction);',
'    apex_json.write(''config_json'', r.config_json);',
'    apex_json.write(''knowledge_core_id'', r.knowledge_core_id);',
'    apex_json.write(',
'        ''has_active_knowledge_core'',',
'        r.has_active_knowledge_core',
'    );',
'    apex_json.write(''created_at'', r.created_at);',
'    apex_json.write(',
'        ''has_active_collection_binding'',',
'        r.has_active_collection_binding',
'    );',
'    apex_json.write(''row_version'', r.row_version);',
'    apex_json.close_object;',
'end loop;',
'',
'apex_json.close_array;',
'apex_json.close_object;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48405033366827728)
,p_internal_uid=>48428807631830386
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48428969891830386)
,p_process_sequence=>15
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_LOAD_RESOURCE_CATALOG'
,p_static_id=>'p30-load-resource-catalog'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    function uuid_text(p_value raw) return varchar2 is',
'        l_hex varchar2(32) := rawtohex(p_value);',
'    begin',
'        return lower(',
'            substr(l_hex, 1, 8) || ''-'' || substr(l_hex, 9, 4) || ''-'' ||',
'            substr(l_hex, 13, 4) || ''-'' || substr(l_hex, 17, 4) || ''-'' ||',
'            substr(l_hex, 21, 12)',
'        );',
'    end;',
'begin',
'    apex_json.open_object;',
'    apex_json.open_array(''collections'');',
'    for r in (',
'        select collection_id, display_name, status',
'          from kbot_kc_collection',
'         where domain_id = :P0_DOMAIN_ID',
'           and status = ''ACTIVE''',
'         order by upper(display_name), collection_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''collection_id'', uuid_text(r.collection_id));',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48405033366827728)
,p_internal_uid=>48428969891830386
);
end;
