,p_region_name=>'p40-collection-report'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as collection_id,',
'       c.display_name,',
'       c.status,',
'       c.updated_at,',
'       (select count(distinct e.document_version_id) from kbot_kc_evidence e where e.collection_id = c.collection_id and e.status = ''ACTIVE'') as searchable_file_count,',
'       (select count(*) from kbot_kc_bundle_revision r where r.collection_id = c.collection_id and r.approval_status = ''PENDING'') as pending_approval_count,',
'       (select count(*) from kbot_kc_bundle_revision r where r.collection_id = c.collection_id and r.status in (''ACCEPTED'', ''PROCESSING'')) as processing_revision_count,',
'       (select count(*) from kbot_kc_bundle_revision r where r.collection_id = c.collection_id and r.status = ''FAILED'') as failed_revision_count,',
'       lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as parsed_collection_id,',
'       lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as upload_collection_id,',
'       lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as approval_collection_id,',
'       lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as delete_collection_id,',
'       lower(substr(rawtohex(c.collection_id), 1, 8) || ''-'' || substr(rawtohex(c.collection_id), 9, 4) || ''-'' || substr(rawtohex(c.collection_id), 13, 4) || ''-'' || substr(rawtohex(c.collection_id), 17, 4) || ''-'' || substr(rawtohex(c.collection_id), 2'
||'1, 12)) as processing_collection_id,',
'       null as edit_action',
'  from kbot_kc_collection c',
' where c.domain_id = :P0_DOMAIN_ID',
' order by c.display_name'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
