wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48432623271830388)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P40_LOAD_KNOWLEDGE_SUMMARY'
,p_static_id=>'p40-load-knowledge-summary'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_collection_count       number := 0;',
'    l_ready_file_count       number := 0;',
'    l_pending_approval_count number := 0;',
'    l_processing_count       number := 0;',
'    l_failed_count           number := 0;',
'begin',
'    select count(*)',
'      into l_collection_count',
'      from kbot_kc_collection',
'     where domain_id = :P0_DOMAIN_ID;',
'',
'    select count(distinct e.document_version_id)',
'      into l_ready_file_count',
'      from kbot_kc_collection c',
'      join kbot_kc_evidence e',
'        on e.collection_id = c.collection_id',
'       and e.status = ''ACTIVE''',
'     where c.domain_id = :P0_DOMAIN_ID;',
'',
'    select nvl(sum(',
'               case when r.approval_status = ''PENDING''',
'                    then 1 else 0 end',
'           ), 0),',
'           nvl(sum(',
'               case when r.status in (',
'                   ''ACCEPTED'',',
'                   ''PROCESSING''',
'               ) then 1 else 0 end',
'           ), 0),',
'           nvl(sum(',
'               case when r.status = ''FAILED''',
'                    then 1 else 0 end',
'           ), 0)',
'      into l_pending_approval_count,',
'           l_processing_count,',
'           l_failed_count',
'      from kbot_kc_bundle_revision r',
'      join kbot_kc_collection c',
'        on c.collection_id = r.collection_id',
'     where c.domain_id = :P0_DOMAIN_ID;',
'',
'    apex_json.open_object;',
'    apex_json.write(',
'        ''collection_count'',',
'        l_collection_count',
'    );',
'    apex_json.write(',
'        ''ready_file_count'',',
'        l_ready_file_count',
'    );',
'    apex_json.write(',
'        ''pending_approval_count'',',
'        l_pending_approval_count',
'    );',
'    apex_json.write(',
'        ''processing_count'',',
'        l_processing_count',
'    );',
'    apex_json.write(''failed_count'', l_failed_count);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48432623271830388
);
end;
