'window.kbotGetCollectionListUrl = function () {',
'    return new Promise((resolve, reject) => {',
'        apex.server.process(',
'            "P41_GET_COLLECTION_LIST_URL",',
'            {pageItems: "#P0_DOMAIN_ID"},',
'            {',
'                dataType: "json",',
'                success: function (payload) {',
'                    if (!payload?.url) {',
unistr('                        reject(new Error("\672A\80FD\751F\6210\77E5\8BC6\5E93\5217\8868\9875\5730\5740\3002"));'),
'                        return;',
'                    }',
'                    resolve(payload.url);',
'                },',
'                error: function (jqXHR, textStatus, errorThrown) {',
'                    reject(new Error(String(',
'                        jqXHR?.responseJSON?.error',
'                        || jqXHR?.responseText',
'                        || errorThrown',
'                        || textStatus',
unistr('                        || "\672A\80FD\8FD4\56DE\77E5\8BC6\5E93\5217\8868\9875\3002"'),
'                    )));',
'                }',
'            }',
'        );',
'    });',
'};',
'',
'window.kbotCreateCollection = async function () {',
'        const value = (itemName) => apex.item(itemName).getValue().trim();',
'        const modelUuid = (itemName, label) => {',
'            const compact = value(itemName).toLowerCase().replace(/-/g, "");',
'            const uuid = compact.length === 32',
'                ? `${compact.slice(0, 8)}-${compact.slice(8, 12)}-${compact.slice(12, 16)}-${compact.slice(16, 20)}-${compact.slice(20)}`',
'                : "";',
'            if (!/^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid)) {',
unistr('                throw new Error(`${label} \5FC5\987B\9009\62E9\5DF2\914D\7F6E\7684 UUIDv7 \6A21\578B\3002`);'),
'            }',
'            return uuid;',
'        };',
'        const requiredItems = [',
'            "P0_DOMAIN_ID",',
'            "P41_DISPLAY_NAME",',
'            "P41_PARSER_LLM",',
'            "P41_RETRIEVAL_LLM",',
'            "P41_EMBEDDING",',
'            "P41_SECURITY_LEVEL"',
'        ];',
'        const missing = requiredItems.filter((itemName) => !value(itemName));',
'        apex.message.clearErrors();',
'        if (missing.length) {',
'            apex.message.showErrors([{',
'                type: "error",',
'                location: "page",',
unistr('                message: "\8BF7\586B\5199\6240\6709\5FC5\586B\7684\77E5\8BC6\5E93\914D\7F6E\9879\3002",'),
'                unsafe: false',
'            }]);',
'            return;',
'        }',
'',
'        const spinner = apex.util.showSpinner(document.body);',
'        try {',
'            const optionalValue = (itemName) => value(itemName) || null;',
'            const models = {',
unistr('                parser_llm: modelUuid("P41_PARSER_LLM", "\89E3\6790\5927\8BED\8A00\6A21\578B"),'),
unistr('                retrieval_llm: modelUuid("P41_RETRIEVAL_LLM", "\68C0\7D22\5927\8BED\8A00\6A21\578B"),'),
unistr('                embedding: modelUuid("P41_EMBEDDING", "\6587\672C\5411\91CF\6A21\578B")'),
'            };',
'            const parserVlm = optionalValue("P41_PARSER_VLM");',
'            const visualEmbedding = optionalValue("P41_VISUAL_EMBEDDING");',
'            if (parserVlm) {',
unistr('                models.parser_vlm = modelUuid("P41_PARSER_VLM", "\89E3\6790\89C6\89C9\6A21\578B");'),
