'            if (visualEmbedding) {',
unistr('                models.visual_embedding = modelUuid("P41_VISUAL_EMBEDDING", "\89C6\89C9\5411\91CF\6A21\578B");'),
'            }',
'            const requestBody = {',
'                display_name: value("P41_DISPLAY_NAME"),',
'                models,',
'                description: optionalValue("P41_DESCRIPTION"),',
'                default_security_level: Number(value("P41_SECURITY_LEVEL")),',
'                metadata: {}',
'            };',
