'                method: "POST",',
unistr('                label: "\521B\5EFA\77E5\8BC6\5E93",'),
'                body: JSON.stringify(requestBody)',
'            });',
'            const collectionId = String(responseBody?.collection_id || "").trim();',
'            if (!collectionId) {',
unistr('                throw new Error("\77E5\8BC6\5E93\5DF2\521B\5EFA\FF0C\4F46\54CD\5E94\4E2D\7F3A\5C11 collection_id\3002");'),
'            }',
'',
'            const listUrl = await kbotGetCollectionListUrl();',
'',
'            spinner.remove();',
'            sessionStorage.setItem(',
'                "kbot.collection.success",',
unistr('                `\77E5\8BC6\5E93\201C${value("P41_DISPLAY_NAME")}\201D\521B\5EFA\6210\529F\3002`'),
'            );',
'            apex.navigation.redirect(listUrl);',
'        } catch (error) {',
'            spinner.remove();',
'            apex.message.showErrors([{',
'                type: "error",',
'                location: "page",',
unistr('                message: error.message || "\521B\5EFA\77E5\8BC6\5E93\5931\8D25\3002",'),
'                unsafe: false',
'            }]);',
'        }',
'};',
'',
'window.kbotPrepareCollectionForm = function () {',
'    const successMessage = sessionStorage.getItem("kbot.collection.success");',
'    if (successMessage) {',
'        sessionStorage.removeItem("kbot.collection.success");',
'        apex.message.showPageSuccess(successMessage);',
'    }',
'    if (!apex.item("P41_COLLECTION_ID").getValue()) {',
'        apex.item("P41_STATUS").hide();',
'        return;',
'    }',
'    window.kbotInitialCollectionModels = JSON.stringify({',
'        parser_llm: apex.item("P41_PARSER_LLM").getValue().trim(),',
'        retrieval_llm: apex.item("P41_RETRIEVAL_LLM").getValue().trim(),',
'        embedding: apex.item("P41_EMBEDDING").getValue().trim(),',
'        parser_vlm: apex.item("P41_PARSER_VLM").getValue().trim() || null,',
