'    window.kbotInitialCollectionStatus = apex.item("P41_STATUS").getValue().trim();',
'    apex.item("P41_EMBEDDING").disable();',
'    if (apex.item("P41_VISUAL_EMBEDDING").getValue()) {',
'        apex.item("P41_VISUAL_EMBEDDING").disable();',
'    }',
'};',
'',
'window.kbotUpdateCollection = async function () {',
'    const value = (itemName) => apex.item(itemName).getValue().trim();',
'    const requiredItems = [',
'        "P0_DOMAIN_ID",',
'        "P41_COLLECTION_ID",',
'        "P41_DISPLAY_NAME",',
'        "P41_PARSER_LLM",',
'        "P41_RETRIEVAL_LLM",',
'        "P41_EMBEDDING",',
'        "P41_SECURITY_LEVEL",',
'        "P41_STATUS",',
'        "P41_ROW_VERSION"',
'    ];',
'    const missing = requiredItems.filter((itemName) => !value(itemName));',
'    apex.message.clearErrors();',
'    if (missing.length) {',
'        apex.message.showErrors([{',
'            type: "error",',
'            location: "page",',
unistr('            message: "\77E5\8BC6\5E93\914D\7F6E\4E0D\5B8C\6574\FF0C\8BF7\5237\65B0\9875\9762\540E\91CD\8BD5\3002",'),
'            unsafe: false',
'        }]);',
'        return;',
