'',
'    const collectionId = value("P41_COLLECTION_ID");',
'',
'    const spinner = apex.util.showSpinner(document.body);',
'    try {',
'        const comparableModels = {',
'            parser_llm: value("P41_PARSER_LLM"),',
'            retrieval_llm: value("P41_RETRIEVAL_LLM"),',
'            embedding: value("P41_EMBEDDING"),',
'            parser_vlm: value("P41_PARSER_VLM") || null,',
'            visual_embedding: value("P41_VISUAL_EMBEDDING") || null',
'        };',
'        const models = {',
'            parser_llm: comparableModels.parser_llm,',
'            retrieval_llm: comparableModels.retrieval_llm,',
'            embedding: comparableModels.embedding',
'        };',
'        if (comparableModels.parser_vlm) {',
'            models.parser_vlm = comparableModels.parser_vlm;',
'        }',
'        if (comparableModels.visual_embedding) {',
'            models.visual_embedding = comparableModels.visual_embedding;',
