wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48436341398830442)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\52A0\8F7D\77E5\8BC6\5E93\7F16\8F91\6570\636E')
,p_static_id=>'p41-load-collection-for-edit'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_collection_id varchar2(36) := :P41_COLLECTION_ID;',
'begin',
'    select c.display_name,',
'       pl.model_id,',
'       rl.model_id,',
'       em.model_id,',
'       pv.model_id,',
'       ve.model_id,',
'       c.default_security_level,',
'       c.description,',
'       c.status,',
'       c.row_version into :P41_DISPLAY_NAME,',
'       :P41_PARSER_LLM,',
'       :P41_RETRIEVAL_LLM,',
'       :P41_EMBEDDING,',
'       :P41_PARSER_VLM,',
'       :P41_VISUAL_EMBEDDING,',
'       :P41_SECURITY_LEVEL,',
'       :P41_DESCRIPTION,',
'       :P41_STATUS,',
'       :P41_ROW_VERSION',
'      from kbot_kc_collection c',
'      left join kbot_ai_model pl',
'        on pl.model_id = hextoraw(replace(json_value(c.models_json, ''$.parser_llm''), ''-'', ''''))',
'      left join kbot_ai_model rl',
'        on rl.model_id = hextoraw(replace(json_value(c.models_json, ''$.retrieval_llm''), ''-'', ''''))',
'      left join kbot_ai_model em',
'        on em.model_id = hextoraw(replace(json_value(c.models_json, ''$.embedding''), ''-'', ''''))',
'      left join kbot_ai_model pv',
'        on pv.model_id = hextoraw(replace(json_value(c.models_json, ''$.parser_vlm''), ''-'', ''''))',
'      left join kbot_ai_model ve',
'        on ve.model_id = hextoraw(replace(json_value(c.models_json, ''$.visual_embedding''), ''-'', ''''))',
'     where c.domain_id = :P0_DOMAIN_ID',
'       and c.collection_id = hextoraw(replace(v_collection_id, ''-'', ''''));',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P41_COLLECTION_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>48436341398830442
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48436534215830442)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P41_UPDATE_COLLECTION_DETAILS'
,p_static_id=>'p41-update-collection-details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_collection_id  varchar2(36) := trim(apex_application.g_x01);',
'    v_expected       number := to_number(apex_application.g_x02);',
'    v_security_level number := to_number(:P41_SECURITY_LEVEL);',
'    v_row_version    number;',
'begin',
'    if trim(:P41_DISPLAY_NAME) is null then',
unistr('        raise_application_error(-20001, ''\77E5\8BC6\5E93\540D\79F0\4E0D\80FD\4E3A\7A7A\3002'');'),
'    end if;',
'    if v_security_level < 0 or v_security_level > 999 then',
unistr('        raise_application_error(-20002, ''\9ED8\8BA4\5B89\5168\7EA7\522B\5FC5\987B\4ECB\4E8E 0 \548C 999 \4E4B\95F4\3002'');'),
'    end if;',
'',
'    update kbot_kc_collection',
'       set display_name = trim(:P41_DISPLAY_NAME),',
'           description = :P41_DESCRIPTION,',
'           default_security_level = v_security_level,',
'           updated_by = :APP_USER,',
'           updated_at = current_timestamp,',
'           row_version = row_version + 1',
'     where domain_id = :P0_DOMAIN_ID',
'       and collection_id = hextoraw(replace(v_collection_id, ''-'', ''''))',
'       and row_version = v_expected;',
'',
'    if sql%rowcount = 0 then',
unistr('        raise_application_error(-20003, ''\77E5\8BC6\5E93\5DF2\88AB\5176\4ED6\8BF7\6C42\4FEE\6539\FF0C\8BF7\5237\65B0\540E\91CD\8BD5\3002'');'),
'    end if;',
'',
'    select row_version',
'      into v_row_version',
'      from kbot_kc_collection',
'     where domain_id = :P0_DOMAIN_ID',
'       and collection_id = hextoraw(replace(v_collection_id, ''-'', ''''));',
'',
'    apex_json.open_object;',
'    apex_json.write(''row_version'', v_row_version);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48407805154827729)
,p_internal_uid=>48436534215830442
);
end;
