prompt --application/pages/page_00042
begin
wwv_flow_imp_page.create_page(
 p_id=>42
,p_name=>unistr('\6587\4EF6\5165\5E93\5411\5BFC')
,p_alias=>'FILE-INGESTION'
,p_step_title=>unistr('\77E5\8BC6\4E2D\5FC3-\6587\4EF6\5165\5E93\5411\5BFC')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_html_page_header=>'<script src="#APP_FILES#js/kbot-theme-init.js?v=20260812_2"></script>'
,p_javascript_file_urls=>'#APP_FILES#js/knowledge-flow.js?v=20260928_18'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.kbotFileUploadMimeType = function (file) {',
'    const fileName = String(file?.name || "").trim().toLowerCase();',
'    const browserMimeType = String(file?.type || "").trim().toLowerCase();',
'',
'    if (fileName.endsWith(".pdf")) {',
'        return "application/pdf";',
'    }',
'    return browserMimeType || "application/octet-stream";',
'};',
'',
'window.KbotFileQueue = class {',
'    constructor() {',
'        this.files = [];',
'        this.initialized = false;',
'    }',
'',
'    fileKey(file) {',
'        return [file.name, file.size, file.lastModified].join("::");',
'    }',
'',
'    formatSize(size) {',
'        if (!Number.isFinite(size) || size <= 0) {',
'            return "0 B";',
'        }',
'        const units = ["B", "KB", "MB", "GB"];',
'        const unitIndex = Math.min(Math.floor(Math.log(size) / Math.log(1024)), units.length - 1);',
'        const value = size / Math.pow(1024, unitIndex);',
'        return `${value.toFixed(unitIndex === 0 ? 0 : 2)} ${units[unitIndex]}`;',
'    }',
'',
'    addFiles(fileList) {',
'        const existingKeys = new Set(this.files.map((file) => this.fileKey(file)));',
'        Array.from(fileList || []).forEach((file) => {',
'            const key = this.fileKey(file);',
'            if (!existingKeys.has(key)) {',
'                this.files.push(file);',
'                existingKeys.add(key);',
'            }',
'        });',
'        this.render();',
'    }',
'',
'    removeFile(index) {',
'        if (index >= 0 && index < this.files.length) {',
'            this.files.splice(index, 1);',
'            this.render();',
'        }',
'    }',
'',
'    clearFiles() {',
'        this.files = [];',
'        const fileInput = document.getElementById("P42_FILES");',
'        if (fileInput) {',
'            fileInput.value = "";',
'        }',
'        this.render();',
'    }',
'',
'    render() {',
'        const body = document.getElementById("p42-file-rows");',
'        const summary = document.getElementById("p42-file-summary-text");',
'        const clearButton = document.getElementById("p42-clear-files");',
'        if (!body || !summary || !clearButton) {',
'            return;',
'        }',
'',
'        body.replaceChildren();',
'        const totalBytes = this.files.reduce((total, file) => total + file.size, 0);',
'        summary.textContent = this.files.length',
unistr('            ? `\5DF2\9009\62E9 ${this.files.length} \4E2A\6587\4EF6\FF0C\5171 ${this.formatSize(totalBytes)}`'),
unistr('            : "\5C1A\672A\9009\62E9\6587\4EF6";'),
'        clearButton.hidden = this.files.length === 0;',
'',
'        if (!this.files.length) {',
'            const row = document.createElement("tr");',
'            const cell = document.createElement("td");',
'            cell.colSpan = 4;',
'            cell.className = "p42-file-empty";',
unistr('            cell.textContent = "\8BF7\9009\62E9\4E00\4E2A\6216\591A\4E2A\6587\4EF6\3002";'),
'            row.appendChild(cell);',
'            body.appendChild(row);',
'            return;',
'        }',
'',
'        this.files.forEach((file, index) => {',
'            const row = document.createElement("tr");',
'            const nameCell = document.createElement("td");',
'            const sizeCell = document.createElement("td");',
'            const typeCell = document.createElement("td");',
'            const actionCell = document.createElement("td");',
'            const removeButton = document.createElement("button");',
'            const removeIcon = document.createElement("span");',
'            const removeText = document.createElement("span");',
'',
'            nameCell.className = "p42-file-name";',
'            nameCell.textContent = file.name;',
'            sizeCell.textContent = this.formatSize(file.size);',
'            typeCell.textContent = window.kbotFileUploadMimeType(file);',
'',
'            removeButton.type = "button";',
'            removeButton.className = "t-Button t-Button--noLabel t-Button--icon t-Button--danger";',
'            removeButton.dataset.fileIndex = String(index);',
unistr('            removeButton.title = `\5220\9664 ${file.name}`;'),
unistr('            removeButton.setAttribute("aria-label", `\5220\9664 ${file.name}`);'),
'            removeIcon.className = "t-Icon fa fa-trash";',
'            removeIcon.setAttribute("aria-hidden", "true");',
'            removeText.className = "u-VisuallyHidden";',
unistr('            removeText.textContent = "\5220\9664";'),
'            removeButton.append(removeIcon, removeText);',
'            actionCell.className = "p42-file-actions";',
'            actionCell.appendChild(removeButton);',
'',
'            row.append(nameCell, sizeCell, typeCell, actionCell);',
'            body.appendChild(row);',
'        });',
'    }',
'',
'    init() {',
'        if (this.initialized) {',
'            this.render();',
'            return;',
'        }',
'        const fileInput = document.getElementById("P42_FILES");',
'        const fileRows = document.getElementById("p42-file-rows");',
'        const clearButton = document.getElementById("p42-clear-files");',
'        if (!fileInput || !fileRows || !clearButton) {',
'            return;',
'        }',
'',
'        fileInput.addEventListener("change", () => {',
'            this.addFiles(fileInput.files);',
'            fileInput.value = "";',
'        });',
'        fileRows.addEventListener("click", (event) => {',
'            const button = event.target.closest("button[data-file-index]");',
'            if (button) {',
'                this.removeFile(Number(button.dataset.fileIndex));',
'            }',
'        });',
'        clearButton.addEventListener("click", () => this.clearFiles());',
'        this.initialized = true;',
'        this.render();',
'    }',
'};',
'window.kbotFileQueue = new window.KbotFileQueue();',
'',
'window.kbotInitFileIngestion = function () {',
'    window.kbotFileQueue.init();',
'    window.kbotSyncBundleFields();',
'',
'    const groupingMode = document.getElementById("P42_GROUPING_MODE");',
