'       ) as mime_type,',
'       case',
'           when dv.byte_size is null then ''-''',
'           when dv.byte_size < 1024',
'               then to_char(dv.byte_size) || '' B''',
'           when dv.byte_size < 1048576',
'               then to_char(',
'                   round(dv.byte_size / 1024, 2)',
'               ) || '' KB''',
'           else to_char(',
'               round(dv.byte_size / 1048576, 2)',
'           ) || '' MB''',
'       end as file_size,',
'       ir.receipt_status,',
'       nvl(br.approval_status, ''-'') as approval_status,',
'       nvl(br.status, ''-'') as revision_status,',
'       nvl(m.member_status, ''-'') as file_status,',
'       nvl(',
'           b.availability_status,',
'           ''-''',
'       ) as availability_status,',
'       coalesce(',
'           m.failure_code,',
'           br.failure_code,',
'           ir.failure_code',
'       ) as error_code,',
'       coalesce(',
'           m.failure_message,',
'           br.failure_message,',
'           ir.failure_message',
'       ) as error_message,',
'       ir.actor_id,',
'       ir.created_at',
'  from kbot_kc_ingestion_receipt ir',
'  join kbot_kc_collection c',
'    on c.collection_id = ir.collection_id',
'  left join kbot_kc_bundle b',
'    on b.bundle_id = ir.bundle_id',
'   and b.collection_id = ir.collection_id',
'  left join kbot_kc_bundle_revision br',
'    on br.bundle_revision_id =',
'       ir.bundle_revision_id',
'   and br.collection_id = ir.collection_id',
'  left join kbot_kc_bundle_revision_document m',
'    on m.bundle_revision_id =',
'       ir.bundle_revision_id',
'   and m.collection_id = ir.collection_id',
'   and m.document_role <> ''MANIFEST''',
'  left join kbot_kc_document_version dv',
'    on dv.document_version_id =',
'       m.document_version_id',
'   and dv.collection_id = m.collection_id',
' where c.domain_id = :P0_DOMAIN_ID',
'   and c.collection_id =',
'       hextoraw(replace(:P42_COLLECTION_ID, ''-'', ''''))',
' order by ir.created_at desc,',
'          m.ordinal'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_DOMAIN_ID,P42_COLLECTION_ID'
,p_lazy_loading=>false
