,p_prompt=>unistr('\5386\53F2\8D44\6599\5305')
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select max(br.title) keep (dense_rank last order by br.revision_no) || ''\FF08\7248\672C '' || to_char(max(br.revision_no)) || ''\FF09'' as display_value,'),
'       b.source_id as return_value',
'  from kbot_kc_bundle b',
'  join kbot_kc_bundle_revision br',
'    on br.bundle_id = b.bundle_id',
'   and br.collection_id = b.collection_id',
' where b.collection_id = hextoraw(replace(:P42_COLLECTION_ID, ''-'', ''''))',
'   and b.availability_status <> ''DELETING''',
' group by b.bundle_id,',
'          b.source_id',
