,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.kbotResetApprovals = function () {',
'    const tbody = document.getElementById("p43-approval-rows");',
'    const statusNode = document.getElementById("p43-approval-status");',
'    if (statusNode) {',
unistr('        statusNode.textContent = "\8BF7\9009\62E9\77E5\8BC6\5E93\540E\67E5\8BE2\3002";'),
'    }',
'    if (tbody) {',
'        const row = document.createElement("tr");',
'        const cell = document.createElement("td");',
'        cell.colSpan = 5;',
unistr('        cell.textContent = "\5C1A\672A\67E5\8BE2\3002";'),
'        row.appendChild(cell);',
'        tbody.replaceChildren(row);',
'    }',
'    apex.item("P43_SELECTED_REVISION_ID").setValue("");',
'    apex.item("P43_DECISION").setValue("");',
'    kbotUpdateApprovalSelection();',
'};',
'',
'window.kbotHandleApprovalCollectionChange = function () {',
'    const collectionId = String(apex.item("P43_COLLECTION_ID").getValue() || "").trim();',
'    const historyRegion = apex.region("p43-approval-history");',
'    if (historyRegion) {',
'        historyRegion.refresh();',
'    }',
'    if (collectionId) {',
'        kbotLoadApprovals();',
'    } else {',
'        kbotResetApprovals();',
'    }',
'};',
'',
'window.kbotLoadApprovals = async function () {',
'    const domainId = String(apex.item("P0_DOMAIN_ID").getValue() || "").trim();',
'    const collectionId = String(apex.item("P43_COLLECTION_ID").getValue() || "").trim();',
'    const tbody = document.getElementById("p43-approval-rows");',
'    const statusNode = document.getElementById("p43-approval-status");',
'    const showError = (message) => {',
'        apex.message.clearErrors();',
'        apex.message.showErrors([{',
'            type: "error",',
'            location: "page",',
'            message,',
'            unsafe: false',
'        }]);',
'    };',
'',
'    if (!domainId) {',
unistr('        showError("\8BF7\9009\62E9\4E1A\52A1\57DF\3002");'),
'        return;',
'    }',
'    if (!collectionId) {',
unistr('        showError("\8BF7\9009\62E9\9700\8981\5904\7406\7684\77E5\8BC6\5E93\3002");'),
'        return;',
'    }',
'    const spinner = apex.util.showSpinner(document.body);',
unistr('    statusNode.textContent = "\6B63\5728\8BFB\53D6\5F85\5BA1\6279\7248\672C\2026";'),
'    tbody.replaceChildren();',
'    try {',
'        const payload = await KBotApi.request(',
'            `/api/v1/apps/knowledge-retrieval/knowledge/collections/${encodeURIComponent(collectionId)}/approvals`,',
unistr('            { label: "\8BFB\53D6\5F85\5BA1\6279\5217\8868", cacheKey: `p43:approvals:${collectionId}`, ttl: 10000 }'),
'        );',
'',
'        const items = Array.isArray(payload.items) ? payload.items : [];',
'        if (!items.length) {',
'            const row = document.createElement("tr");',
'            const cell = document.createElement("td");',
'            cell.colSpan = 5;',
unistr('            cell.textContent = "\5F53\524D\77E5\8BC6\5E93\6CA1\6709\5F85\5BA1\6279\7248\672C\3002";'),
'            row.appendChild(cell);',
'            tbody.appendChild(row);',
'        }',
'        items.forEach((item) => {',
'            const row = document.createElement("tr");',
'            const selectCell = document.createElement("td");',
'            const titleCell = document.createElement("td");',
'            const revisionCell = document.createElement("td");',
'            const documentsCell = document.createElement("td");',
'            const actionCell = document.createElement("td");',
'            titleCell.textContent = item.title || "-";',
'            revisionCell.textContent = item.bundle_revision_id || "-";',
'            documentsCell.textContent = Array.isArray(item.document_names)',
unistr('                ? item.document_names.join("\3001")'),
'                : "-";',
'',
'            const selectBox = document.createElement("input");',
'            selectBox.type = "checkbox";',
'            selectBox.className = "p43-approval-select";',
'            selectBox.value = item.bundle_revision_id || "";',
unistr('            selectBox.setAttribute("aria-label", `\9009\62E9 ${item.title || "\5F85\5BA1\7248\672C"}`);'),
'            selectBox.addEventListener("change", kbotUpdateApprovalSelection);',
'            selectCell.appendChild(selectBox);',
'',
'            const approveButton = document.createElement("button");',
'            approveButton.type = "button";',
'            approveButton.className = "t-Button t-Button--small t-Button--success";',
unistr('            approveButton.textContent = "\2713 \6279\51C6";'),
'            approveButton.dataset.revisionId = item.bundle_revision_id || "";',
'            approveButton.dataset.decision = "APPROVE";',
'',
'            const rejectButton = document.createElement("button");',
'            rejectButton.type = "button";',
'            rejectButton.className = "t-Button t-Button--small t-Button--danger";',
unistr('            rejectButton.textContent = "\2715 \9A73\56DE";'),
'            rejectButton.dataset.revisionId = item.bundle_revision_id || "";',
'            rejectButton.dataset.decision = "REJECT";',
'',
'            [approveButton, rejectButton].forEach((button) => {',
'                button.addEventListener("click", () => {',
'                    apex.item("P43_SELECTED_REVISION_ID").setValue(button.dataset.revisionId);',
'                    apex.item("P43_DECISION").setValue(button.dataset.decision);',
'                    kbotReviewApproval();',
'                });',
'                actionCell.appendChild(button);',
'            });',
'            row.append(selectCell, titleCell, revisionCell, documentsCell, actionCell);',
'            tbody.appendChild(row);',
'        });',
'        kbotUpdateApprovalSelection();',
unistr('        statusNode.textContent = `\5F53\524D\6709 ${items.length} \4E2A\8D44\6599\5305\7B49\5F85\5BA1\6279\3002`;'),
'        apex.message.clearErrors();',
'    } catch (error) {',
unistr('        statusNode.textContent = error.message || "\8BFB\53D6\5F85\5BA1\6279\5217\8868\5931\8D25\3002";'),
unistr('        showError(error.message || "\8BFB\53D6\5F85\5BA1\6279\5217\8868\5931\8D25\3002");'),
'    } finally {',
'        spinner.remove();',
'    }',
'};',
'',
'window.kbotUpdateApprovalSelection = function () {',
'    const boxes = [...document.querySelectorAll(".p43-approval-select")];',
'    const selected = boxes.filter((box) => box.checked).length;',
'    const selectAll = document.getElementById("p43-select-all");',
'    const countNode = document.getElementById("p43-selected-count");',
'',
'    if (countNode) {',
unistr('        countNode.textContent = `\5DF2\9009\62E9 ${selected} \9879`;'),
'    }',
'    document.querySelectorAll(".p43-bulk-action").forEach((button) => {',
'        button.disabled = selected === 0;',
'    });',
'    if (selectAll) {',
'        selectAll.checked = boxes.length > 0 && selected === boxes.length;',
'        selectAll.indeterminate = selected > 0 && selected < boxes.length;',
'    }',
'};',
'',
'window.kbotToggleAllApprovals = function (checked) {',
'    document.querySelectorAll(".p43-approval-select").forEach((box) => {',
'        box.checked = checked;',
'    });',
'    kbotUpdateApprovalSelection();',
'};',
'',
'window.kbotRequestApproval = async function (',
'    collectionId,',
'    revisionId,',
'    decision,',
'    comment',
') {',
'    return KBotApi.request(',
'        `/api/v1/apps/knowledge-retrieval/knowledge/collections/${encodeURIComponent(collectionId)}/bundle-revisions/${encodeURIComponent(revisionId)}/approval`,',
'        {',
'            method: "POST",',
'            body: JSON.stringify({ decision, comment }),',
unistr('            label: "\63D0\4EA4\5165\5E93\5BA1\6279"'),
'        }',
'    );',
'};',
'',
'window.kbotBulkReviewApprovals = async function (decision) {',
'    const revisionIds = [...document.querySelectorAll(".p43-approval-select:checked")]',
'        .map((box) => box.value)',
'        .filter(Boolean);',
'    const domainId = String(apex.item("P0_DOMAIN_ID").getValue() || "").trim();',
'    const collectionId = String(apex.item("P43_COLLECTION_ID").getValue() || "").trim();',
'    const comment = String(apex.item("P43_COMMENT").getValue() || "").trim() || null;',
'    const statusNode = document.getElementById("p43-approval-status");',
'    const showError = (message) => {',
'        apex.message.clearErrors();',
'        apex.message.showErrors([{ type: "error", location: "page", message, unsafe: false }]);',
'    };',
'',
'    if (!domainId || !collectionId || !revisionIds.length || !["APPROVE", "REJECT"].includes(decision)) {',
unistr('        showError("\8BF7\9009\62E9\9700\8981\6279\91CF\5904\7406\7684\5F85\5BA1\7248\672C\3002");'),
'        return;',
'    }',
'    if (decision === "REJECT" && !comment) {',
unistr('        showError("\6279\91CF\9A73\56DE\65F6\8BF7\586B\5199\5BA1\6279\610F\89C1\3002");'),
'        return;',
'    }',
unistr('    const actionName = decision === "APPROVE" ? "\6279\51C6" : "\9A73\56DE";'),
unistr('    if (!window.confirm(`\786E\8BA4\6279\91CF${actionName}\5DF2\9009\62E9\7684 ${revisionIds.length} \4E2A\7248\672C\FF1F`)) {'),
'        return;',
'    }',
'',
'    const spinner = apex.util.showSpinner(document.body);',
unistr('    statusNode.textContent = `\6B63\5728\6279\91CF${actionName} ${revisionIds.length} \4E2A\7248\672C\2026`;'),
'    let results;',
'    try {',
'        results = await Promise.allSettled(',
'            revisionIds.map((revisionId) => kbotRequestApproval(',
'                collectionId,',
'                revisionId,',
'                decision,',
'                comment',
'            ))',
'        );',
'    } finally {',
'        spinner.remove();',
'    }',
'',
'    const succeeded = results.filter((result) => result.status === "fulfilled").length;',
'    const failed = results.length - succeeded;',
'    if (succeeded) {',
'        apex.item("P43_COMMENT").setValue("");',
'    }',
'    apex.region("p43-approval-history")?.refresh();',
'    KBotApi.clearCache(`p43:approvals:${collectionId}`);',
'    await kbotLoadApprovals();',
'',
'    if (!failed) {',
unistr('        apex.message.showPageSuccess(`\6279\91CF${actionName}\5B8C\6210\FF0C\5171\5904\7406 ${succeeded} \9879\3002`);'),
'        return;',
'    }',
'    const firstFailure = results.find((result) => result.status === "rejected");',
unistr('    showError(`\6279\91CF${actionName}\5B8C\6210\FF1A\6210\529F ${succeeded} \9879\FF0C\5931\8D25 ${failed} \9879\3002\9996\4E2A\9519\8BEF\FF1A${firstFailure.reason?.message || "\8BF7\6C42\5931\8D25"}`);'),
'};',
'',
'window.kbotReviewApproval = async function () {',
'    const domainId = String(apex.item("P0_DOMAIN_ID").getValue() || "").trim();',
'    const collectionId = String(apex.item("P43_COLLECTION_ID").getValue() || "").trim();',
'    const revisionId = String(apex.item("P43_SELECTED_REVISION_ID").getValue() || "").trim();',
'    const decision = String(apex.item("P43_DECISION").getValue() || "").trim();',
'    const comment = String(apex.item("P43_COMMENT").getValue() || "").trim() || null;',
'    const statusNode = document.getElementById("p43-approval-status");',
'    const showError = (message) => {',
'        apex.message.clearErrors();',
'        apex.message.showErrors([{',
'            type: "error",',
'            location: "page",',
'            message,',
'            unsafe: false',
'        }]);',
'    };',
'',
'    if (!domainId || !collectionId || !revisionId || !["APPROVE", "REJECT"].includes(decision)) {',
unistr('        showError("\5BA1\6279\76EE\6807\6216\5BA1\6279\51B3\5B9A\65E0\6548\FF0C\8BF7\5237\65B0\5217\8868\540E\91CD\8BD5\3002");'),
'        return;',
'    }',
'    if (decision === "REJECT" && !comment) {',
unistr('        showError("\9A73\56DE\65F6\8BF7\586B\5199\5BA1\6279\610F\89C1\3002");'),
'        return;',
'    }',
'',
'    const spinner = apex.util.showSpinner(document.body);',
'    statusNode.textContent = decision === "APPROVE"',
unistr('        ? "\6B63\5728\6279\51C6\5E76\521B\5EFA\89E3\6790\4EFB\52A1\2026"'),
unistr('        : "\6B63\5728\9A73\56DE\7248\672C\2026";'),
'    try {',
'        await kbotRequestApproval(',
'            collectionId,',
'            revisionId,',
'            decision,',
'            comment',
'        );',
'        apex.item("P43_COMMENT").setValue("");',
'        apex.message.showPageSuccess(',
'            decision === "APPROVE"',
unistr('                ? "\5BA1\6279\901A\8FC7\FF0C\89E3\6790\4EFB\52A1\5DF2\521B\5EFA\3002"'),
unistr('                : "\5DF2\9A73\56DE\FF0C\8BE5\7248\672C\4E0D\4F1A\8FDB\5165\89E3\6790\3002"'),
'        );',
'        const historyRegion = apex.region("p43-approval-history");',
'        if (historyRegion) {',
'            historyRegion.refresh();',
'        }',
'        KBotApi.clearCache(`p43:approvals:${collectionId}`);',
'        await kbotLoadApprovals();',
'    } catch (error) {',
unistr('        statusNode.textContent = error.message || "\5165\5E93\5BA1\6279\5931\8D25\3002";'),
unistr('        showError(error.message || "\5165\5E93\5BA1\6279\5931\8D25\3002");'),
'    } finally {',
'        spinner.remove();',
'    }',
'};'))
