'select nvl(m.declared_name, br.title) as file_name,',
'       br.revision_no,',
'       br.approval_status,',
'       br.reviewed_by,',
'       br.reviewed_at,',
'       br.review_comment,',
'       coalesce(m.failure_message, br.failure_message) as failure_message',
'  from kbot_kc_collection c',
'  join kbot_kc_bundle_revision br',
'    on br.collection_id = c.collection_id',
'  left join kbot_kc_bundle_revision_document m',
'    on m.bundle_revision_id = br.bundle_revision_id',
'   and m.collection_id = br.collection_id',
'   and m.document_role <> ''MANIFEST''',
' where c.domain_id = :P0_DOMAIN_ID',
'   and c.collection_id = hextoraw(replace(:P43_COLLECTION_ID, ''-'', ''''))',
' order by br.created_at desc,',
'          m.ordinal'))
