wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(48443980471830500)
,p_name=>unistr('\53EF\68C0\7D22\6587\4EF6\6E05\5355')
,p_static_id=>'p44-parsed-file-report'
,p_region_name=>'p44-parsed-file-report'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select coalesce(',
'           m.declared_name,',
'           m.external_document_id,',
'           dv.storage_uri',
'       ) as file_name,',
'       nvl(',
'           m.declared_mime_type,',
'           dv.detected_mime_type',
'       ) as mime_type,',
'       case',
'           when dv.byte_size < 1024',
'               then to_char(dv.byte_size) || '' B''',
'           when dv.byte_size < 1048576',
'               then to_char(',
'                   round(dv.byte_size / 1024, 2)',
'               ) || '' KB''',
'           else to_char(',
'               round(dv.byte_size / 1048576, 2)',
'           ) || '' MB''',
'       end as file_size,',
'       dv.version_no,',
'       dv.security_level,',
'       count(*) as evidence_count,',
'       listagg(',
'           distinct e.evidence_type,',
'           '', ''',
'       ) within group (',
'           order by e.evidence_type',
'       ) as evidence_types,',
'       case',
'           when min(e.page_start) is null',
'               and max(e.page_end) is null',
'               then ''-''',
'           when min(e.page_start) =',
'                max(e.page_end)',
'               then to_char(min(e.page_start))',
'           else nvl(',
'                    to_char(min(e.page_start)),',
'                    ''?''',
'                ) || '' - '' ||',
'                nvl(',
'                    to_char(max(e.page_end)),',
'                    ''?''',
'                )',
'       end as page_range,',
'       sum(nvl(e.token_count, 0)) as token_count,',
'       listagg(',
'           distinct pv.parser_name,',
'           '', ''',
'       ) within group (',
'           order by pv.parser_name',
'       ) as parsers,',
'       max(pv.quality_score) as quality_score,',
'       case',
'           when count(*) = count(e.indexed_at)',
unistr('               then ''\5DF2\7D22\5F15'''),
'           when count(e.indexed_at) > 0',
unistr('               then ''\90E8\5206\7D22\5F15'''),
unistr('           else ''\672A\7D22\5F15'''),
'       end as index_status,',
'       max(e.indexed_at) as indexed_at,',
'       max(e.updated_at) as updated_at,',
'       lower(',
'           substr(rawtohex(e.collection_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(e.collection_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(e.collection_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(e.collection_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(e.collection_id), 21, 12)',
'       ) as collection_id,',
'       lower(',
'           substr(rawtohex(dv.bundle_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(dv.bundle_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(dv.bundle_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(dv.bundle_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(dv.bundle_id), 21, 12)',
'       ) as bundle_id,',
'       lower(',
'           substr(rawtohex(dv.document_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(dv.document_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_id), 21, 12)',
'       ) as document_id,',
'       lower(',
'           substr(rawtohex(dv.document_version_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(dv.document_version_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_version_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_version_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(dv.document_version_id), 21, 12)',
'       ) as document_version_id',
'  from kbot_kc_collection c',
'  join kbot_kc_evidence e',
'    on e.collection_id = c.collection_id',
'   and e.status = ''ACTIVE''',
'  join kbot_kc_document_version dv',
'    on dv.document_version_id =',
'       e.document_version_id',
'   and dv.collection_id =',
'       e.collection_id',
'  left join kbot_kc_bundle_revision_document m',
'    on m.bundle_revision_document_id =',
'       e.bundle_revision_document_id',
'   and m.bundle_revision_id =',
'       e.bundle_revision_id',
'   and m.collection_id =',
'       e.collection_id',
'  join kbot_kc_parse_view pv',
'    on pv.parse_view_id =',
'       e.parse_view_id',
'   and pv.collection_id =',
'       e.collection_id',
' where c.domain_id = :P0_DOMAIN_ID',
'   and c.collection_id =',
'       hextoraw(replace(:P44_COLLECTION_ID, ''-'', ''''))',
' group by e.document_version_id,',
'          coalesce(',
'              m.declared_name,',
'              m.external_document_id,',
'              dv.storage_uri',
'          ),',
'          nvl(',
'              m.declared_mime_type,',
'              dv.detected_mime_type',
'          ),',
'          dv.byte_size,',
'          dv.version_no,',
'          dv.security_level,',
'          e.collection_id,',
'          dv.bundle_id,',
'          dv.document_id,',
'          dv.document_version_id',
' order by max(e.updated_at) desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_DOMAIN_ID,P44_COLLECTION_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>unistr('\5F53\524D\77E5\8BC6\5E93\5C1A\65E0 ACTIVE \8BC1\636E\FF0C\56E0\6B64\6682\65F6\6CA1\6709\53EF\68C0\7D22\6587\4EF6\3002')
,p_query_num_rows_type=>'ROW_RANGES_WITH_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
