 p_id=>wwv_flow_imp.id(48447306089830554)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P45_LOAD_DOCUMENT_PREVIEW'
,p_static_id=>'p45-load-document-preview'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_document_id         raw(16);',
'    l_document_version_id raw(16);',
'    l_collection_id       raw(16);',
'    l_bundle_id           raw(16);',
'    l_found               boolean := false;',
'begin',
'    apex_json.open_object;',
'',
'    begin',
'        l_document_id :=',
'            hextoraw(replace(trim(:P45_DOCUMENT_ID), ''-'', ''''));',
'        l_document_version_id :=',
'            hextoraw(',
'                replace(',
'                    trim(:P45_DOCUMENT_VERSION_ID),',
'                    ''-'',',
'                    ''''',
'                )',
'            );',
'        l_collection_id :=',
'            hextoraw(',
'                replace(trim(:P45_COLLECTION_ID), ''-'', '''')',
'            );',
'        l_bundle_id :=',
'            hextoraw(replace(trim(:P45_BUNDLE_ID), ''-'', ''''));',
'    exception',
'        when others then',
'            apex_json.write(',
'                ''error'',',
unistr('                ''\5F15\7528\53C2\6570\683C\5F0F\4E0D\6B63\786E\FF0C\65E0\6CD5\6253\5F00\6587\4EF6\9884\89C8\3002'''),
'            );',
'            apex_json.close_object;',
'            return;',
'    end;',
'',
'    for item in (',
'        select c.display_name as collection_name,',
'               coalesce(',
'                   m.declared_name,',
'                   d.external_document_id,',
'                   dv.storage_uri',
'               ) as file_name,',
'               nvl(',
'                   m.declared_mime_type,',
'                   dv.detected_mime_type',
'               ) as mime_type,',
'               dv.byte_size,',
'               dv.version_no,',
'               dv.security_level,',
'               dv.storage_state,',
'               dv.received_at,',
'               (',
'                   select count(*)',
'                     from kbot_kc_evidence e',
'                    where e.collection_id =',
'                              dv.collection_id',
'                      and e.document_id =',
'                              dv.document_id',
'                      and e.document_version_id =',
'                              dv.document_version_id',
'                      and e.status = ''ACTIVE''',
'               ) as evidence_count',
'          from kbot_kc_document d',
'          join kbot_kc_document_version dv',
'            on dv.document_id = d.document_id',
'           and dv.collection_id = d.collection_id',
'           and dv.bundle_id = d.bundle_id',
'          join kbot_kc_collection c',
'            on c.collection_id = d.collection_id',
'          left join',
'               kbot_kc_bundle_revision_document m',
'            on m.document_id = d.document_id',
'           and m.document_version_id =',
'               dv.document_version_id',
'           and m.collection_id = d.collection_id',
'         where c.domain_id = to_number(:P0_DOMAIN_ID)',
'           and d.document_id = l_document_id',
'           and dv.document_version_id =',
'               l_document_version_id',
'           and d.collection_id = l_collection_id',
'           and d.bundle_id = l_bundle_id',
'         order by m.updated_at desc nulls last',
'         fetch first 1 row only',
'    ) loop',
'        l_found := true;',
'        apex_json.open_object(''document'');',
'        apex_json.write(',
'            ''collection_name'',',
'            item.collection_name',
'        );',
'        apex_json.write(''file_name'', item.file_name);',
'        apex_json.write(''mime_type'', item.mime_type);',
'        apex_json.write(''byte_size'', item.byte_size);',
'        apex_json.write(''version_no'', item.version_no);',
'        apex_json.write(',
'            ''security_level'',',
'            item.security_level',
'        );',
'        apex_json.write(',
'            ''storage_state'',',
'            item.storage_state',
'        );',
'        apex_json.write(',
'            ''received_at'',',
'            to_char(',
'                item.received_at,',
'                ''YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM''',
'            )',
'        );',
'        apex_json.write(',
'            ''evidence_count'',',
'            item.evidence_count',
'        );',
'        apex_json.close_object;',
'    end loop;',
'',
'    if not l_found then',
'        apex_json.write(',
'            ''error'',',
unistr('            ''\5F53\524D\4E1A\52A1\57DF\4E2D\672A\627E\5230\8BE5\5F15\7528\6587\4EF6\FF0C\6216\6587\4EF6\6807\8BC6\4E0D\5339\914D\3002'''),
'        );',
'        apex_json.close_object;',
'        return;',
'    end if;',
'',
'    apex_json.open_array(''evidence'');',
'    for item in (',
'        select e.ordinal,',
'               e.fragment_index,',
'               e.evidence_type,',
'               e.page_start,',
'               e.page_end,',
'               e.source_item_ref,',
'               e.content_text',
'          from kbot_kc_evidence e',
'          join kbot_kc_collection c',
'            on c.collection_id = e.collection_id',
'         where c.domain_id = to_number(:P0_DOMAIN_ID)',
'           and e.collection_id = l_collection_id',
'           and e.document_id = l_document_id',
'           and e.document_version_id =',
'               l_document_version_id',
'           and e.status = ''ACTIVE''',
'         order by e.ordinal, e.fragment_index',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''ordinal'', item.ordinal);',
'        apex_json.write(',
'            ''fragment_index'',',
'            item.fragment_index',
'        );',
'        apex_json.write(',
'            ''evidence_type'',',
'            item.evidence_type',
'        );',
'        apex_json.write(',
'            ''page_start'',',
'            item.page_start',
'        );',
'        apex_json.write(''page_end'', item.page_end);',
'        apex_json.write(',
'            ''source_item_ref'',',
'            item.source_item_ref',
'        );',
'        apex_json.write(',
'            ''content_text'',',
'            item.content_text',
'        );',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48447306089830554
);
end;
