,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with latest_parse_view as (select pv.*, row_number() over (partition by pv.document_version_id order by pv.updated_at desc, pv.created_at desc) as rn from kbot_kc_parse_view pv where pv.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', ''''))),',
'     latest_parse_job as (select j.*, row_number() over (partition by j.document_version_id order by j.created_at desc) as rn from kbot_kc_ingestion_job j where j.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', '''')) and j.job_type = ''PARSE'''
||'),',
'     latest_index_job as (select j.*, row_number() over (partition by j.document_version_id order by j.created_at desc) as rn from kbot_kc_ingestion_job j where j.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', '''')) and j.job_type = ''INDEX'''
||'),',
'     latest_discovery_job as (',
'         select j.*,',
'                row_number() over (partition by j.bundle_revision_id order by j.created_at desc) as rn',
'           from kbot_kc_ingestion_job j',
'          where j.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', ''''))',
'            and j.job_type = ''INDEX''',
'            and upper(json_value(j.payload_json, ''$.target'' returning varchar2(32) null on error)) = ''DISCOVERY''',
'            and json_value(j.payload_json, ''$.reindex_generation'' returning varchar2(128) null on error) is null',
'     )',
'select apex_escape.html(nvl(m.declared_name, m.external_document_id)) as file_name,',
'       br.title as revision_title,',
'       br.revision_no,',
'       br.approval_status,',
'       m.member_status,',
'       nvl(pv.view_status, ''-'') as parse_view_status,',
'       nvl(pj.job_status, ''-'') as parse_job_status,',
'       nvl(ij.job_status, ''-'') as index_job_status,',
'       nvl(pj.attempt_count, 0) || ''/'' || nvl(pj.max_attempts, 0) as parse_attempts,',
'       nvl(ij.attempt_count, 0) || ''/'' || nvl(ij.max_attempts, 0) as index_attempts,',
'       coalesce(m.failure_stage, ij.failure_class, pj.failure_class) as failure_stage,',
'       coalesce(m.failure_code, ij.failure_code, pj.failure_code) as failure_code,',
'       coalesce(m.failure_message, ij.failure_message, pj.failure_message) as failure_message,',
'       coalesce(ij.trace_id, pj.trace_id) as trace_id,',
'       greatest(m.updated_at, nvl(pv.updated_at, m.updated_at), nvl(pj.updated_at, m.updated_at), nvl(ij.updated_at, m.updated_at)) as updated_at,',
'       lower(substr(rawtohex(m.document_version_id), 1, 8) || ''-'' || substr(rawtohex(m.document_version_id), 9, 4) || ''-'' || substr(rawtohex(m.document_version_id), 13, 4) || ''-'' || substr(rawtohex(m.document_version_id), 17, 4) || ''-'' || substr(rawt'
||'ohex(m.document_version_id), 21, 12)) as document_version_id,',
'       lower(substr(rawtohex(br.bundle_id), 1, 8) || ''-'' || substr(rawtohex(br.bundle_id), 9, 4) || ''-'' || substr(rawtohex(br.bundle_id), 13, 4) || ''-'' || substr(rawtohex(br.bundle_id), 17, 4) || ''-'' || substr(rawtohex(br.bundle_id), 21, 12)) as bund'
||'le_id,',
'       lower(substr(rawtohex(br.bundle_revision_id), 1, 8) || ''-'' || substr(rawtohex(br.bundle_revision_id), 9, 4) || ''-'' || substr(rawtohex(br.bundle_revision_id), 13, 4) || ''-'' || substr(rawtohex(br.bundle_revision_id), 17, 4) || ''-'' || substr(rawt'
||'ohex(br.bundle_revision_id), 21, 12)) as bundle_revision_id,',
'       case',
'           when br.approval_status in (''APPROVED'', ''NOT_REQUIRED'')',
'            and pj.job_status in (''SUCCEEDED'', ''FAILED'')',
'            and m.document_version_id is not null',
'            and nvl(m.document_role, ''CONTENT'') <> ''MANIFEST''',
'           then ''Y''',
'           else ''N''',
'       end as can_reprocess,',
'       ''REPROCESS'' as reprocess_action,',
'       ''JOBS'' as job_action,',
'       case',
'           when b.current_revision_id = br.bundle_revision_id',
'            and b.availability_status in (''READY'', ''PARTIAL'')',
'           then ''PUBLISHED''',
'           when current_br.revision_no > br.revision_no',
'           then ''SUPERSEDED''',
'           when dj.job_status = ''FAILED''',
'           then ''FAILED''',
'           else ''PUBLISHING''',
'       end as publication_status',
'  from kbot_kc_bundle_revision_document m',
'  join kbot_kc_bundle_revision br',
'    on br.bundle_revision_id = m.bundle_revision_id',
'   and br.collection_id = m.collection_id',
'  join kbot_kc_bundle b',
'    on b.bundle_id = br.bundle_id',
'   and b.collection_id = br.collection_id',
'  left join kbot_kc_bundle_revision current_br',
'    on current_br.bundle_revision_id = b.current_revision_id',
'   and current_br.bundle_id = b.bundle_id',
'   and current_br.collection_id = b.collection_id',
'  left join latest_parse_view pv',
'    on pv.document_version_id = m.document_version_id',
'   and pv.rn = 1',
'  left join latest_parse_job pj',
'    on pj.document_version_id = m.document_version_id',
'   and pj.rn = 1',
'  left join latest_index_job ij',
'    on ij.document_version_id = m.document_version_id',
'   and ij.rn = 1',
'  left join latest_discovery_job dj',
'    on dj.bundle_revision_id = br.bundle_revision_id',
'   and dj.rn = 1',
' where m.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', ''''))',
'   and (:P46_MEMBER_STATUS is null or m.member_status = :P46_MEMBER_STATUS)',
' order by greatest(m.updated_at, nvl(pv.updated_at, m.updated_at), nvl(pj.updated_at, m.updated_at), nvl(ij.updated_at, m.updated_at)) desc,',
'          m.ordinal'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P46_COLLECTION_ID,P46_MEMBER_STATUS'
