'select s.total_files,',
'       s.processing_files,',
'       s.ready_files,',
'       s.failed_files,',
'       (select count(*) from kbot_kc_ingestion_job j where j.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', '''')) and j.job_type in (''PARSE'', ''INDEX'') and j.job_status in (''PENDING'', ''RUNNING'', ''RETRY_WAIT'')) as active_jobs',
'  from (select count(*) as total_files, nvl(sum(case when m.member_status in (''RECEIVED'', ''PARSING'', ''INDEXING'') then 1 else 0 end), 0) as processing_files, nvl(sum(case when m.member_status = ''READY'' then 1 else 0 end), 0) as ready_files, nvl(sum(ca'
||'se when m.member_status in (''FAILED'', ''SOURCE_UNAVAILABLE'', ''CANCELLED'') then 1 else 0 end), 0) as failed_files from kbot_kc_bundle_revision_document m where m.collection_id = hextoraw(replace(:P46_COLLECTION_ID, ''-'', ''''))) s'))
