wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48455392004830603)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P47_GET_EVIDENCE_FALLBACK'
,p_static_id=>'p47-get-evidence-fallback'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_run_id             raw(16);',
'    l_document_version   varchar2(64);',
'    l_title              varchar2(512);',
'    l_page_no            number;',
'    l_count              pls_integer := 0;',
'begin',
'    if not regexp_like(',
'           apex_application.g_x01,',
'           ''^[0-9a-fA-F]{8}-?[0-9a-fA-F]{4}-?'' ||',
'           ''[0-9a-fA-F]{4}-?[0-9a-fA-F]{4}-?'' ||',
'           ''[0-9a-fA-F]{12}$''',
'       ) or not regexp_like(',
'           apex_application.g_x02,',
'           ''^C[1-9][0-9]*$''',
'       ) then',
unistr('        raise_application_error(-20001, ''\5F15\7528\5B9A\4F4D\53C2\6570\65E0\6548\3002'');'),
'    end if;',
'',
'    l_run_id := hextoraw(',
'        replace(apex_application.g_x01, ''-'', '''')',
'    );',
'',
'    select jt.document_version_id,',
'           jt.title,',
'           jt.page_no',
'      into l_document_version,',
'           l_title,',
'           l_page_no',
'      from kbot_agent_run r',
'      join kbot_agent_artifact a',
'        on a.artifact_id = r.result_artifact_id',
'       and a.run_id = r.run_id',
'      cross apply json_table(',
'          a.payload_json,',
'          ''$.references[*]''',
'          columns (',
'              reference_type varchar2(32)',
'                  path ''$.reference_type'',',
'              citation_label varchar2(32)',
'                  path ''$.citation_label'',',
'              title varchar2(512)',
'                  path ''$.title'',',
'              document_version_id varchar2(64)',
'                  path ''$.document_version_id'',',
'              page_no number',
'                  path ''$.locator.pages[0].page_no''',
'          )',
'      ) jt',
'     where r.run_id = l_run_id',
'       and r.domain_id = :P0_DOMAIN_ID',
'       and r.actor_id = :APP_USER',
'       and jt.reference_type = ''DOCUMENT''',
'       and jt.citation_label = apex_application.g_x02;',
'',
'    apex_json.open_object;',
'    apex_json.write(''title'', l_title);',
'    apex_json.write(''page_no'', l_page_no);',
'    apex_json.open_array(''fragments'');',
'',
'    for r in (',
'        select e.ordinal,',
'               e.page_start,',
'               e.page_end,',
'               dbms_lob.substr(e.content_text, 12000, 1)',
'                   as content_text',
'          from kbot_kc_evidence e',
'         where e.document_version_id = hextoraw(',
'                   replace(l_document_version, ''-'', '''')',
'               )',
'           and e.status = ''ACTIVE''',
'           and (',
'               l_page_no is null',
'               or l_page_no between',
'                   nvl(e.page_start, l_page_no)',
'                   and nvl(e.page_end, l_page_no)',
'           )',
'         order by e.ordinal, e.fragment_index',
'         fetch first 12 rows only',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''ordinal'', r.ordinal);',
'        apex_json.write(''page_start'', r.page_start);',
'        apex_json.write(''page_end'', r.page_end);',
'        apex_json.write(''text'', r.content_text);',
'        apex_json.close_object;',
'        l_count := l_count + 1;',
'    end loop;',
'',
'    apex_json.close_array;',
'    apex_json.write(''count'', l_count);',
'    apex_json.close_object;',
'exception',
'    when no_data_found then',
'        raise_application_error(',
'            -20002,',
unistr('            ''\5F53\524D\7528\6237\65E0\6743\8BBF\95EE\8BE5\5F15\7528\FF0C\6216\5F15\7528\8BC1\636E\4E0D\5B58\5728\3002'''),
'        );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48455392004830603
);
end;
